class Graph:
    def __init__(self):
        """Initialize an empty graph with an adjacency list."""
        self.adj_list = {}

    def add_vertex(self, vertex):
        """Add a vertex to the graph if it does not already exist."""
        if vertex not in self.adj_list:
            self.adj_list[vertex] = []
            return True
        return False

    def add_edge(self, vertex1, vertex2):
        """Add an undirected edge between two vertices if both exist in the graph."""
        if vertex1 in self.adj_list and vertex2 in self.adj_list:
            self.adj_list[vertex1].append(vertex2)
            self.adj_list[vertex2].append(vertex1)
            return True
        return False

    def dfs(self, vertex):
        """Perform a depth-first search starting from the given vertex and return the order of visited vertices."""
        result = []
        visited = set()

        def dfs_helper(v):
            if v not in visited:
                visited.add(v)
                result.append(v)
                for neighbor in self.adj_list[v]:
                    dfs_helper(neighbor)

        dfs_helper(vertex)
        return result
