class SimpleTextEditor:
    def __init__(self):
        self.text = ""  # The content of the text editor
        self.history = []  # A stack to keep track of actions for undo functionality

    def insert(self, position, char):
        """Insert a character at a specified position."""
        if position < 0 or position > len(self.text):
            raise ValueError("Position out of bounds")
        self.history.append(('insert', position, self.text[position:position+1]))
        self.text = self.text[:position] + char + self.text[position:]

    def delete(self, position):
        """Delete a character at a specified position."""
        if position < 0 or position >= len(self.text):
            raise ValueError("Position out of bounds")
        self.history.append(('delete', position, self.text[position]))
        self.text = self.text[:position] + self.text[position+1:]

    def undo(self):
        """Undo the last action (either insert or delete)."""
        if not self.history:
            raise Exception("Nothing to undo")
        last_action = self.history.pop()
        action_type, position, char = last_action
        if action_type == 'insert':
            self.text = self.text[:position] + self.text[position+1:]
        elif action_type == 'delete':
            self.text = self.text[:position] + char + self.text[position:]
