class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_string = False

class SubstringFinder:
    def __init__(self):
        self.root = TrieNode()

    def addString(self, string):
        """
        Adds a new string to the collection.

        :param string: The string to be added.
        """
        node = self.root
        for char in string:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_string = True

    def findSubstrings(self, string):
        """
        Finds all substrings of the given string that appear in the collection.

        :param string: The string to search for substrings.
        :return: A list of unique substrings found in the collection.
        """
        substrings = set()

        def dfs(start, node, path):
            if node.is_end_of_string:
                substrings.add(path)
            if start >= len(string):
                return
            if string[start] in node.children:
                dfs(start + 1, node.children[string[start]], path + string[start])

        for i in range(len(string)):
            dfs(i, self.root, "")

        return list(substrings)
