class Fibonacci:
    def __init__(self):
        self.memo = {}

    def fibonacci(self, n):
        """
        Computes the nth Fibonacci number using memoization.

        :param n: An integer representing the position in the Fibonacci sequence.
        :return: The nth Fibonacci number.
        """
        if n in self.memo:
            return self.memo[n]
        if n <= 0:
            return 0
        elif n == 1:
            return 1
        else:
            self.memo[n] = self.fibonacci(n - 1) + self.fibonacci(n - 2)
            return self.memo[n]

