import heapq

class RunningMedian:
    def __init__(self):
        self.max_heap = []  # Inverted min-heap to simulate max-heap
        self.min_heap = []  # Min-heap

    def add_number(self, num):
        """Adds a number to the running median data structure."""
        if len(self.max_heap) == len(self.min_heap):
            heapq.heappush(self.min_heap, -heapq.heappushpop(self.max_heap, -num))
        else:
            heapq.heappush(self.max_heap, -heapq.heappushpop(self.min_heap, num))

    def get_median(self):
        """Returns the current running median."""
        if len(self.max_heap) > len(self.min_heap):
            return -self.max_heap[0]
        else:
            return (-self.max_heap[0] + self.min_heap[0]) / 2.0

def running_median(stream):
    """Calculates the running median for a stream of integers."""
    rm = RunningMedian()
    medians = []
    for number in stream:
        rm.add_number(number)
        medians.append(rm.get_median())
    return medians
