def wiggleMaxLength(nums):
    """
    Returns the length of the longest wiggle subsequence in the given list of integers.

    :param nums: List[int] - A list of integers representing the sequence.
    :return: int - The length of the longest wiggle subsequence.
    """
    if not nums or len(nums) < 2:
        return len(nums)

    up = 1
    down = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            up = down + 1
        elif nums[i] < nums[i - 1]:
            down = up + 1

    return max(up, down)

