import math

class Vector2D:
    def __init__(self, x=0.0, y=0.0):
        self.x = x
        self.y = y

    def add(self, other):
        """Returns a new Vector2D object representing the sum of the current vector and other."""
        return Vector2D(self.x + other.x, self.y + other.y)

    def subtract(self, other):
        """Returns a new Vector2D object representing the difference between the current vector and other."""
        return Vector2D(self.x - other.x, self.y - other.y)

    def dot(self, other):
        """Returns the dot product of the current vector and other."""
        return self.x * other.x + self.y * other.y

    def magnitude(self):
        """Returns the magnitude of the current vector."""
        return math.sqrt(self.x ** 2 + self.y ** 2)

    def __repr__(self):
        return f"Vector2D(x={self.x}, y={self.y})"
