def sum_primes(n):
    """
    Computes the sum of all prime numbers less than a given number n.

    :param n: An integer representing the upper limit.
    :return: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0], sieve[1] = False, False

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n, start):
                sieve[multiple] = False

    return sum(index for index, is_prime in enumerate(sieve) if is_prime)
