def sum_of_primes(n):
    """Calculate the sum of the first n prime numbers."""
    sum_primes = 0
    count = 0
    candidate = 1

    while count < n:
        candidate += 1
        if is_prime(candidate):
            count += 1
            sum_primes += candidate

    return sum_primes

