def count_divisors(n):
    """Counts the number of divisors of an integer n."""
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
    return count

def sort_by_divisors(numbers):
    """Sorts a list of integers by the number of divisors, and by value if counts are equal."""
