import math

class Point2D:
    def __init__(self, x=0.0, y=0.0):
        """Initialize a new 2D point with coordinates (x, y)."""
        self.x = x
        self.y = y

    def distance_to(self, other):
        """Calculate the Euclidean distance between this point and another point."""
        if not isinstance(other, Point2D):
            raise ValueError("The argument must be an instance of Point2D")
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    @staticmethod
    def midpoint(p1, p2):
        """Calculate the midpoint between two points."""
        if not isinstance(p1, Point2D) or not isinstance(p2, Point2D):
            raise ValueError("Both arguments must be instances of Point2D")
        mid_x = (p1.x + p2.x) / 2
        mid_y = (p1.y + p2.y) / 2
        return Point2D(mid_x, mid_y)

    def __str__(self):
        """Return the string representation of the point."""
        return f"Point2D({self.x}, {self.y})"
