class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def add(self, data):
        """
        Adds a new node with the specified data to the end of the list.
        """
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def remove(self, data):
        """
        Removes the first node with the specified data from the list.
        Returns a message indicating whether the data was removed or not found.
        """
        current = self.head
        previous = None

        while current:
            if current.data == data:
                if previous:
                    previous.next = current.next
                else:
                    self.head = current.next
                return f"Removed {data}"
            previous = current
            current = current.next

        return f"Data {data} not found in the list"

    def display(self):
        """
        Returns a string representation of the list.
        """
        current = self.head
        nodes = []
        while current:
            nodes.append(str(current.data))
            current = current.next
        return ' -> '.join(nodes) if nodes else "List is empty"
