def parse_chemical_formula(formula):
    """
    Parses a chemical formula and returns a dictionary of elements and their counts.

    :param formula: A string representing a chemical formula.
    :return: A dictionary with elements as keys and their counts as values.
    """
    element = ""
    count = ""
    elements_count = {}

    for char in formula:
        if char.isupper():
            if element:
                elements_count[element] = int(count) if count else 1
                count = ""
            element = char
        elif char.islower():
            element += char
        elif char.isnumeric():
            count += char

    if element:
        elements_count[element] = int(count) if count else 1

    return elements_count

