def find_integers(n, p, matrix):
    """
    Reconstructs the list of integers from their pairwise sums modulo p.

    :param n: Number of integers
    :param p: Modulo value
    :param matrix: n x n matrix of pairwise sums modulo p
    :return: List of integers
    """
    for a0 in range(p):
        a = [a0]
        consistent = True
        for i in range(1, n):
            ai = (matrix[0][i] - a0) % p
            a.append(ai)
            for j in range(1, i):
                if (a[i] + a[j]) % p != matrix[i][j]:
                    consistent = False
                    break
            if not consistent:
                break
        if consistent:
            for i in range(1, n):
                for j in range(i + 1, n):
                    if (a[i] + a[j]) % p != matrix[i][j]:
                        consistent = False
                        break
                if not consistent:
                    break
            if consistent:
                return a
    return None

