def deep_copy(obj):
    """
    Recursively creates a deep copy of a given object.

    Parameters:
    obj (dict or list): The object to be deep copied.

    Returns:
    dict or list: A new object that is a deep copy of the input object.
    """
    if isinstance(obj, dict):
        new_obj = {}
        for key, value in obj.items():
            new_obj[key] = deep_copy(value)
        return new_obj
    elif isinstance(obj, list):
        new_obj = []
        for item in obj:
            new_obj.append(deep_copy(item))
        return new_obj
    else:
        return obj

