class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, val):
        if not self.head:
            self.head = ListNode(val)
            return
        current = self.head
        while current.next:
            current = current.next
        current.next = ListNode(val)

    def print_list(self):
        current = self.head
        while current:
            print(current.val, end=' ')
            current = current.next
        print()

def remove_elements(head, val):
    """
    Removes all nodes from the linked list that have a value equal to val.

    :param head: ListNode, the head of the linked list
    :param val: int, the value to be removed from the linked list
    :return: ListNode, the head of the modified linked list
    """
    dummy = ListNode(next=head)
    current = dummy
    while current.next:
        if current.next.val == val:
            current.next = current.next.next
        else:
            current = current.next
    return dummy.next

