class BinaryTree:
    class Node:
        def __init__(self, value):
            self.value = value
            self.left = None
            self.right = None

    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a new node with the given value into the binary tree."""
        if not self.root:
            self.root = self.Node(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = self.Node(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = self.Node(value)
            else:
                self._insert_recursively(node.right, value)

    def inorder_traversal(self):
        """Performs an in-order traversal of the tree and returns the values in a list."""
        return self._inorder_traversal_recursively(self.root)

    def _inorder_traversal_recursively(self, node):
        if not node:
            return []
        return (self._inorder_traversal_recursively(node.left) +
                [node.value] +
                self._inorder_traversal_recursively(node.right))

    def find_height(self):
        """Returns the height of the binary tree."""
        return self._find_height_recursively(self.root)

    def _find_height_recursively(self, node):
        if not node:
            return -1  # Base case: an empty tree has height -1
        left_height = self._find_height_recursively(node.left)
        right_height = self._find_height_recursively(node.right)
        return 1 + max(left_height, right_height)
