def is_valid_parentheses(s: str) -> bool:
    """
    Determines if the given string s is a valid parentheses sequence.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is a valid parentheses sequence, otherwise False.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or mapping[char] != stack.pop():
                return False
        else:
            return False
    return not stack

