    print("stack.pop():", stack.pop())    # Output: stack.pop(): 3
    print("stack.pop():", stack.pop())    # Output: stack.pop(): 2
    print("Is stack empty?", stack.is_empty())  # Output: Is stack empty? False
    print("stack.pop():", stack.pop())    # Output: stack.pop(): 1
