        self.val = val
        self.left = left
        self.right = right

def find_path_to_target(root, target):
    """
    Finds the path from the root to the node with the target value in a binary tree.

    :param root: TreeNode, the root of the binary tree.
    :param target: int, the target value to find in the tree.
    :return: List[int], the path from the root to the target node, or an empty list if not found.
    """
    def dfs(node, path):
        if not node:
            return None

        path.append(node.val)

        if node.val == target:
            return path

        left_path = dfs(node.left, path.copy())
        if left_path:
            return left_path

        right_path = dfs(node.right, path.copy())
        if right_path:
            return right_path

        path.pop()
        return None

    return dfs(root, [])
