def find_repeated_substrings(strings, k):
    """
    Finds all substrings of length k that appear at least twice in the list of strings.

    :param strings: List of input strings.
    :param k: Length of the substrings to find.
    :return: A set of substrings of length k that appear at least twice.
    """
    substring_count = {}
    for s in strings:
        for i in range(len(s) - k + 1):
            substring = s[i:i + k]
            if substring in substring_count:
                substring_count[substring] += 1
            else:
                substring_count[substring] = 1
    return {substring for substring, count in substring_count.items() if count > 1}

