class TicTacToe:
    def __init__(self):
        self.board = [' ' for _ in range(9)]  # 3x3 board represented by a list of 9 elements
        self.current_winner = None

    def print_board(self):
        """Prints the current state of the board in a 3x3 format."""
        for row in [self.board[i*3:(i+1)*3] for i in range(3)]:
            print('| ' + ' | '.join(row) + ' |')

    @staticmethod
    def print_board_nums():
        """Prints the board with numbers for reference on how to make a move."""
        number_board = [[str(i) for i in range(j*3, (j+1)*3)] for j in range(3)]
        for row in number_board:
            print('| ' + ' | '.join(row) + ' |')

    def available_moves(self):
        """Returns a list of possible moves (indexes of empty spaces in the board)."""
        return [i for i, spot in enumerate(self.board) if spot == ' ']

    def empty_squares(self):
        """Returns True if there are empty squares left on the board, otherwise False."""
        return ' ' in self.board

    def num_empty_squares(self):
        """Returns the number of empty squares left on the board."""
        return self.board.count(' ')

    def make_move(self, square, letter):
        """If valid move, then make the move (assign letter to square) and return True.
        If invalid move, then return False."""
        if self.board[square] == ' ':
            self.board[square] = letter
            if self.winner(square, letter):
                self.current_winner = letter
            return True
        return False

    def winner(self, square, letter):
        """Checks if a recent move was a winning move."""
        # Check for row
        row_ind = square // 3
        row = self.board[row_ind*3:(row_ind+1)*3]
        if all([spot == letter for spot in row]):
            return True
        # Check column
        col_ind = square % 3
        column = [self.board[col_ind+i*3] for i in range(3)]
        if all([spot == letter for spot in column]):
            return True
        # Check diagonals
        if square % 2 == 0:
            diagonal1 = [self.board[i] for i in [0, 4, 8]]
            if all([spot == letter for spot in diagonal1]):
                return True
            diagonal2 = [self.board[i] for i in [2, 4, 6]]
            if all([spot == letter for spot in diagonal2]):
                return True
        return False

def play(game, player1, player2):
    """Actual play function that runs the game."""
    game.print_board_nums()

    letter = 'X'  # starting letter
    # Continue playing while there are empty squares and no winner
    while game.empty_squares():
        # Get move from the current player
        if letter == 'O':
            square = player2.get_move(game)
        else:
            square = player1.get_move(game)
        # Make a move
        if game.make_move(square, letter):
            print(letter + f' makes a move to square {square}')
            game.print_board()
            print('')  # empty line

            if game.current_winner:
                print(letter + ' wins!')
                return letter
            # Switch players
            letter = 'O' if letter == 'X' else 'X'
    print('It\'s a tie!')

class HumanPlayer:
    def __init__(self, letter):
        """Initializes a human player with a specific letter."""
        self.letter = letter

    def get_move(self, game):
        """Prompts the player to make a move and returns the chosen square."""
        valid_square = False
        val = None
        while not valid_square:
            square = input(self.letter + '\'s turn. Input move (0-8): ')
            try:
                val = int(square)
                if val not in game.available_moves():
                    raise ValueError
                valid_square = True
            except ValueError:
                print('Invalid move. Try again.')
        return val

# Example usage:
if __name__ == "__main__":
    x_player = HumanPlayer('X')
    o_player = HumanPlayer('O')
    t = TicTacToe()
    play(t, x_player, o_player)
```

