    def __init__(self):
        """
        Initialize the vending machine with a set of products and coin storage.
        """
        self.products = [
            Product("Soda", 50),  # price in cents
            Product("Chips", 30),
            Product("Candy", 65),
            Product("Water", 20)
        ]
        self.coins = {1: 0, 5: 0, 10: 0, 25: 0}
        self.balance = 0

    def insert_coin(self, coin):
        """
        Insert a coin into the vending machine and update the balance.

        :param coin: Denomination of the coin inserted.
        """
        if coin not in self.coins:
            print("Invalid coin")
            return
        self.coins[coin] += 1
        self.balance += coin
        print(f"Inserted {coin}c. Total balance: {self.balance}c")

    def display_products(self):
        """
        Display the available products and their prices.
        """
        print("Available products:")
        for index, product in enumerate(self.products):
            print(f"({index + 1}) {product.name} - {product.price}c")

    def make_purchase(self, product_index):
        """
        Attempt to purchase a product by its index.

        :param product_index: 1-based index of the product to purchase.
        """
        if 0 < product_index <= len(self.products):
            product = self.products[product_index - 1]
            if self.balance >= product.price:
                self.balance -= product.price
                self.give_change()
                print(f"Dispensing {product.name}")
            else:
                print("Insufficient funds")
        else:
            print("Invalid product selection")

    def give_change(self):
        """
        Provide change for the current balance.
        """
        if self.balance > 0:
            print(f"Giving change: {self.balance}c")
            denominations_order = sorted(self.coins.keys(), reverse=True)  # give high-value coins first
            for coin in denominations_order:
                count = self.balance // coin
                if count > 0:
                    self.coins[coin] -= count
                    print(f" - {count}x {coin}c")
                self.balance -= count * coin

    def main(self):
        """
        Main loop to process commands from the user.
        """
        while True:
            try:
                command = input().strip().split()
                if command[0] == "insert":
                    self.insert_coin(int(command[1]))
                elif command[0] == "purchase":
                    self.make_purchase(int(command[1]))
                elif command[0] == "display":
                    self.display_products()
                elif command[0] == "exit":
                    break
                else:
                    print("Invalid command")
            except ValueError:
                print("Invalid input. Please enter a valid command.")
            except KeyboardInterrupt:
                print("\nExiting the vending machine.")
                break


if __name__ == "__main__":
    vm = VendingMachine()
    vm.main()
