def prime_factors(n, divisor=2, result=None):
    """
    Recursively finds and returns a list of all prime factors of a given positive integer n.

    :param n: The integer to factorize.
    :param divisor: The current divisor being tested.
    :param result: A list to store the prime factors.
    :return: A list of prime factors of n.
    """
    if result is None:
        result = []
    if n <= 1:
        return result
    if n % divisor == 0:
        result.append(divisor)
        return prime_factors(n // divisor, divisor, result)
    else:
        return prime_factors(n, divisor + 1, result)
