def sort_by_vowel_count(strings):
    """
    Sorts a list of strings based on the number of vowels in each string.
    Strings with more vowels come first. In case of a tie, the original order is preserved.

    :param strings: List of strings to be sorted.
    :return: List of strings sorted by the number of vowels in descending order.
    """
    def count_vowels(s):
        vowels = 'aeiouAEIOU'
