def final_position(s):
    """
    Determines the final position of a tile on an infinite grid after executing a series of moves.

    Parameters:
    s (str): A string of moves consisting of 'L', 'R', and 'B'.

    Returns:
    tuple: A tuple (x, y) representing the final coordinates of the tile.
    """
    x = 0
    y = 0

    for move in s:
        if move == 'L':
            x -= 1
        elif move == 'R':
