def string_permutations(s):
    """
    Generator function to yield all permutations of a given string in lexicographical order.

    :param s: A string consisting of distinct characters.
    :yield: Each permutation of the string in lexicographical order.
    """
    if len(s) == 1:
        yield s
    for i, char in enumerate(sorted(s)):
        for permutation in string_permutations(s[:i] + s[i+1:]):
            yield char + permutation
