def invert_dict(d):
    """
    Inverts a dictionary such that keys become values and values become keys.
    If multiple keys have the same value, they are combined into a list.

    :param d: Dictionary with unique integer keys and integer values.
    :return: Dictionary with integer keys and lists of integers as values.
    """
    inverted_dict = {}
    for key, value in d.items():
        if value not in inverted_dict:
            inverted_dict[value] = [key]
        else:
            inverted_dict[value].append(key)
    return inverted_dict
