    :param obj: The JSON object to traverse, which can be a dictionary or a list.
    :param parent_key: A string representing the path to the current key in the JSON structure.
    """
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            traverse_json(value, new_key)
    elif isinstance(obj, list):
        for index, item in enumerate(obj):
            new_key = f"{parent_key}[{index}]"
            traverse_json(item, new_key)
