def is_valid_parentheses(s):
    """
    Determines if the input string s is a valid parentheses sequence.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if s is a valid parentheses sequence, False otherwise.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or mapping[char] != stack.pop():
                return False
        else:
            return False
    return not stack

