class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class CustomLinkedList:
    def __init__(self):
        self.head = None

    def add(self, data):
        """Adds a new element with the specified data to the end of the list."""
        new_node = Node(data)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def remove(self, data):
        """Removes the first occurrence of an element with the specified data from the list.
        Returns True if the element was found and removed, otherwise False."""
        current = self.head
        previous = None
        while current:
            if current.data == data:
                if previous:
                    previous.next = current.next
                else:
                    self.head = current.next
                return True
            previous = current
            current = current.next
        return False

    def search(self, data):
        """Searches for an element with the specified data in the list.
        Returns True if the element is found, otherwise False."""
        current = self.head
        while current:
            if current.data == data:
                return True
            current = current.next
        return False

    def display(self):
        """Prints the entire list as a list of elements."""
        current = self.head
        elements = []
        while current:
            elements.append(current.data)
            current = current.next
        print(elements)
