    def add_book(self, title, num_copies=1):
        """
        Add a new book or update an existing book's quantity.

        :param title: The title of the book to add.
        :param num_copies: The number of copies to add (default is 1).
        :return: A message indicating the number of copies added.
        """
        if title in self.books:
            self.books[title] += num_copies
        else:
            self.books[title] = num_copies
        return f"Added {num_copies} copy(ies) of '{title}'."

    def remove_book(self, title, num_copies=1):
        """
        Remove a certain number of copies of a book, or delete the book if it goes to zero.

        :param title: The title of the book to remove.
        :param num_copies: The number of copies to remove (default is 1).
        :return: A message indicating the number of copies removed or if the book was deleted.
        """
        if title in self.books:
            if num_copies >= self.books[title]:
                del self.books[title]
                return f"All copies of '{title}' have been removed."
            else:
                self.books[title] -= num_copies
                return f"Removed {num_copies} copy(ies) of '{title}'. Remaining copies: {self.books[title]}"
        else:
            return f"'{title}' is not in the library."

    def search_book(self, title):
        """
        Search for the number of available copies of a book.

        :param title: The title of the book to search for.
        :return: A message indicating the number of copies available or if the book is not in the library.
        """
        if title in self.books:
            return f"There are {self.books[title]} copy(ies) of '{title}' available."
        else:
            return f"'{title}' is not in the library."
