def longest_common_substring(strings):
    """
    Finds the length of the longest common substring that appears in all strings.

    :param strings: List of strings to be analyzed.
    :return: Length of the longest common substring.
    """
    if not strings:
        return 0
    min_str = min(strings, key=len)
    length = len(min_str)
    longest = ""

    for start in range(length):
        for end in range(start + 1, length + 1):
            substring = min_str[start:end]
            if all(substring in s for s in strings):
                if len(substring) > len(longest):
                    longest = substring

    return len(longest)
