class FileSystem:
    def __init__(self):
        self.root = {}

    def create_directory(self, path):
        """
        Create a new directory at the specified path.
        :param path: str, the path where the directory should be created.
        """
        nodes = path.strip('/').split('/')
        current = self.root
        for node in nodes:
            if node not in current:
                current[node] = {}
            current = current[node]

    def delete_directory(self, path):
        """
        Delete an existing directory at the specified path.
        :param path: str, the path of the directory to be deleted.
        :raises FileNotFoundError: if the directory does not exist.
        """
        nodes = path.strip('/').split('/')
        current = self.root
        for node in nodes[:-1]:
            current = current.get(node, None)
            if current is None:
                raise FileNotFoundError(f"Directory {path} not found")
        if nodes[-1] in current:
            del current[nodes[-1]]
        else:
            raise FileNotFoundError(f"Directory {path} not found")

    def add_file(self, path, content=''):
        """
        Add a new file with optional content to the specified path.
        :param path: str, the path where the file should be added.
        :param content: str, the content of the file (default is an empty string).
        :raises FileNotFoundError: if the directory path does not exist.
        :raises FileExistsError: if a directory with the same name already exists.
        """
        nodes = path.strip('/').split('/')
        file_name = nodes.pop()
        current = self.root
        for node in nodes:
            current = current.get(node, None)
            if current is None:
                raise FileNotFoundError(f"Directory {'/'.join(nodes)} not found")
        if file_name in current and isinstance(current[file_name], dict):
            raise FileExistsError(f"{path} already exists as a directory")
        current[file_name] = {'content': content}

    def list_contents(self, path):
        """
        List the contents of a directory at the specified path.
        :param path: str, the path of the directory to list.
        :return: dict, the contents of the directory.
        :raises FileNotFoundError: if the directory does not exist.
        """
        nodes = path.strip('/').split('/')
        current = self.root
        for node in nodes:
            current = current.get(node, None)
            if current is None:
                raise FileNotFoundError(f"Directory {path} not found")
        return current

# Example usage
fs = FileSystem()
fs.create_directory('home/user')
fs.create_directory('home/user/documents')
fs.add_file('home/user/documents/report.txt', 'This is a report.')
fs.add_file('home/user/vacation.jpg')
print(fs.list_contents('home/user/documents'))  # Output: {'report.txt': {'content': 'This is a report.'}}
fs.delete_directory('home/user/documents')
print(fs.list_contents('home/user'))  # Output: {'vacation.jpg': {'content': ''}}
