import math

class Point3D:
    def __init__(self, x=0.0, y=0.0, z=0.0):
        """Initialize a new point in 3D space with coordinates x, y, z."""
        self.x = x
        self.y = y
        self.z = z

    def distance_to(self, other):
        """Calculate the Euclidean distance between this point and another point."""
        if not isinstance(other, Point3D):
            raise TypeError("The argument must be an instance of Point3D")
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2 + (self.z - other.z) ** 2)

    def __eq__(self, other):
        """Check if two points are equal."""
        if not isinstance(other, Point3D):
            return False
        return self.x == other.x and self.y == other.y and self.z == other.z

    def __add__(self, other):
        """Add two points by adding their corresponding coordinates."""
        if not isinstance(other, Point3D):
            raise TypeError("The argument must be an instance of Point3D")
        return Point3D(self.x + other.x, self.y + other.y, self.z + other.z)
