import json

def extract_info_from_json(file_path, key):
    """
    Reads a JSON file and extracts all values associated with the specified key.

    Args:
    file_path (str): The path to the JSON file.
    key (str): The key to search for in the JSON data.

    Returns:
    list: A list of values associated with the specified key.
    str: An error message if the file is not found or is not a valid JSON file.
    """
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)

        def search_key(data, target_key):
            if isinstance(data, dict):
                for k, v in data.items():
                    if k == target_key:
                        yield v
                    elif isinstance(v, (dict, list)):
                        yield from search_key(v, target_key)
            elif isinstance(data, list):
                for item in data:
                    yield from search_key(item, target_key)

        return list(search_key(data, key))

    except FileNotFoundError:
        return f"Error: The file {file_path} was not found."
    except json.JSONDecodeError:
        return f"Error: The file {file_path} is not a valid JSON file."
