from collections import defaultdict, deque

def topological_sort(packages):
    """
    Perform a topological sort on a directed acyclic graph represented by a dictionary of packages and their dependencies.

    :param packages: A dictionary where keys are package names and values are lists of dependencies.
    :return: A list of package names in topologically sorted order.
    :raises ValueError: If a cycle exists in the graph, indicating that a topological sort is not possible.
    """
    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for package, dependencies in packages.items():
        graph[package]  # Ensure the package is a key in the graph
        for dependency in dependencies:
            graph[dependency].append(package)
            in_degree[package] += 1

    queue = deque([package for package in packages if in_degree[package] == 0])
    topological_order = []

    while queue:
        package = queue.popleft()
        topological_order.append(package)

        for neighbor in graph[package]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topological_order) == len(packages):
        return topological_order
    else:
        raise ValueError("A cycle exists in graph. Hence, topological sort is not possible.")
