def is_bipartite(graph):
    """
    Determines if a graph represented by an adjacency matrix is bipartite.

    :param graph: List[List[int]], an n x n adjacency matrix representing the graph.
    :return: bool, True if the graph is bipartite, False otherwise.
    """
    n = len(graph)
    colors = [-1] * n

    for start in range(n):
        if colors[start] == -1:
            colors[start] = 0
            queue = [start]

            while queue:
                node = queue.pop(0)

                for neighbor in range(n):
                    if graph[node][neighbor] == 1:
                        if colors[neighbor] != -1:
                            if colors[neighbor] == colors[node]:
                                return False
                        else:
                            colors[neighbor] = 1 - colors[node]
                            queue.append(neighbor)

    return True

# Example usage:
