def remove_outermost_brackets(s: str) -> str:
    """
    Removes the outermost brackets of each group of nested brackets in the string s.

    :param s: A string containing nested brackets.
    :return: A string with the outermost brackets of each group of nested brackets removed.
    """
    result = []
    count = 0
    for char in s:
        if char == '[':
            if count > 0:
                result.append(char)
            count += 1
        elif char == ']':
            count -= 1
            if count > 0:
                result.append(char)
        else:
            result.append(char)
    return ''.join(result)

