        self.value = value
        self.left = left
        self.right = right

def sum_of_nodes(root):
    """
    Computes the sum of all node values in a binary tree.

    :param root: TreeNode, the root of the binary tree
    :return: int, the sum of all node values in the tree
    """
    if root is None:
        return 0
    return root.value + sum_of_nodes(root.left) + sum_of_nodes(root.right)
