def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string.

    Parameters:
    s (str): The input string consisting of lowercase English letters.

    Returns:
    char or None: The first non-repeating character or None if all characters repeat.
    """
    character_count = {}

    for char in s:
        if char in character_count:
            character_count[char] += 1
        else:
