def noOfMaxSquareSubmatrices(N, M, mat):
    """
    Returns the number of square submatrices with the maximum possible side length
    in a given binary matrix mat of dimensions N x M.

    :param N: Number of rows in the matrix
    :param M: Number of columns in the matrix
    :param mat: List of lists representing the binary matrix
    :return: Integer count of the maximum side length square submatrices
    """
    dp = [[0] * M for _ in range(N)]
    max_length = 0

    for i in range(N):
        for j in range(M):
            if mat[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_length = max(max_length, dp[i][j])

    count = 0
    for i in range(N):
        for j in range(M):
            if dp[i][j] == max_length:
                count += 1

    return count
