def is_unique(s):
    """Check if a string has all unique characters."""
    return len(set(s)) == len(s)

def backtrack(words, index, current_word, max_length):
    """Backtrack to find the longest word without repeating characters."""
    max_length[0] = max(max_length[0], len(current_word))
    for i in range(index, len(words)):
        if is_unique(current_word + words[i]):
            backtrack(words, i + 1, current_word + words[i], max_length)

def max_unique_length(words):
    """Find the maximum length of a word that can be formed by concatenating words."""
    max_length = [0]
    backtrack(words, 0, "", max_length)
    return max_length[0]

# Example usage:
