def prime_generator(n):
    """
    Generator function to yield all prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.

    :param n: The upper limit (inclusive) for generating prime numbers.
    :yield: Prime numbers from 2 up to n.
    """
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime numbers
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n + 1, i):
                sieve[j] = False
    for num in range(2, n + 1):
        if sieve[num]:
            yield num

