class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new node with the given key into the binary search tree."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, root, key):
        """Recursive helper function to insert the node."""
        if root is None:
            return TreeNode(key)
        else:
            if root.val < key:
                root.right = self._insert(root.right, key)
            else:
                root.left = self._insert(root.left, key)
        return root

    def find(self, key):
        """Returns True if a node with the given key exists in the tree, otherwise returns False."""
        return self._find(self.root, key)

    def _find(self, root, key):
        """Recursive helper function to find a node."""
        if root is None or root.val == key:
            return root is not None
        if root.val < key:
            return self._find(root.right, key)
        return self._find(root.left, key)

    def delete(self, key):
        """Deletes the node with the given key from the tree if it exists."""
        self.root = self._delete(self.root, key)

    def _delete(self, root, key):
        """Recursive helper function to delete a node."""
        if root is None:
            return root
        if key < root.val:
            root.left = self._delete(root.left, key)
        elif key > root.val:
            root.right = self._delete(root.right, key)
        else:
            if root.left is None:
                return root.right
            elif root.right is None:
                return root.left
            temp = self._minValueNode(root.right)
            root.val = temp.val
            root.right = self._delete(root.right, temp.val)
        return root

    def _minValueNode(self, node):
        """Helper function to find the node with the minimum value."""
        current = node
        while current.left is not None:
            current = current.left
        return current
