def findMin(nums):
    """
    Finds the smallest element in a rotated sorted array of distinct integers.

    :param nums: List[int] - A rotated sorted array of distinct integers.
    :return: int - The smallest element in the array.
    """
    if not nums:
        raise ValueError("Array is empty")

    left, right = 0, len(nums) - 1

    if nums[left] < nums[right]:
        return nums[left]

    while left < right:
        mid = (left + right) // 2

        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    return nums[left]
