class Fibonacci:
    def __init__(self):
        self.cache = {}

    def get_fibonacci(self, n):
        """
        Returns the nth Fibonacci number using memoization.

        :param n: An integer representing the position in the Fibonacci sequence.
        :return: The nth Fibonacci number.
        """
        if n in self.cache:
            return self.cache[n]
        elif n == 0:
            self.cache[n] = 0
        elif n == 1:
            self.cache[n] = 1
        else:
            self.cache[n] = self.get_fibonacci(n-1) + self.get_fibonacci(n-2)
        return self.cache[n]

