def validMountainArray(A):
    """
    Determines if the given list of integers is a valid mountain array.

    :param A: List[int] - A list of integers.
    :return: bool - True if A is a valid mountain array, False otherwise.
    """
    if len(A) < 3:
        return False
    increase = True
    for i in range(1, len(A)):
        if i == 1:
            if A[i] <= A[i-1]:
                return False
        else:
            if A[i] == A[i-1]:
                return False
            if increase and A[i] < A[i-1]:
                increase = False
            if not increase and A[i] > A[i-1]:
                return False
    return not increase
