class VendingMachine:
    def __init__(self):
        """Initialize the vending machine with an empty catalog of items."""
        self.items = {}

    def add_item(self, name, price, quantity):
        """Add or update an item in the vending machine."""
        if name in self.items:
            self.items[name]['quantity'] += quantity
        else:
            self.items[name] = {'price': price, 'quantity': quantity}

    def remove_item(self, name, quantity):
        """Remove a certain quantity of an item from the vending machine."""
        if name in self.items:
            if self.items[name]['quantity'] > quantity:
                self.items[name]['quantity'] -= quantity
            elif self.items[name]['quantity'] == quantity:
                del self.items[name]
            else:
                print(f"Not enough {name} to remove.")
        else:
            print(f"{name} not found in the vending machine.")

    def buy_item(self, name, money):
        """Buy an item from the vending machine, providing money."""
        if name in self.items:
            item = self.items[name]
            if item['quantity'] > 0:
                if money >= item['price']:
                    change = money - item['price']
                    item['quantity'] -= 1
                    print(f"Purchased {name} for ${item['price']:.2f}. Change: ${change:.2f}")
                else:
                    print(f"Not enough money. Missing ${item['price'] - money:.2f}.")
            else:
                print(f"Sorry, {name} is out of stock.")
        else:
            print(f"{name} not found in the vending machine.")

    def display_items(self):
        """Display all items available in the vending machine."""
        if self.items:
            print("Available Items:")
            for name, details in self.items.items():
                print(f"- {name}, Price: ${details['price']:.2f}, Quantity: {details['quantity']}")
        else:
            print("No items available in the vending machine.")
