class MinStack:
    def __init__(self):
        # Initialize two stacks; one to store elements and the other to store the minimum elements
        self.stack = []
        self.min_stack = []

    def push(self, x: int) -> None:
        """Push element x onto stack."""
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self) -> None:
        """Remove the element on top of the stack."""
        if self.stack:
            item = self.stack.pop()
            if item == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self) -> int:
        """Get the top element."""
        if self.stack:
            return self.stack[-1]
        else:
            raise IndexError("Stack is empty")

    def getMin(self) -> int:
        """Retrieve the minimum element in the stack."""
        if self.min_stack:
            return self.min_stack[-1]
        else:
            raise IndexError("Stack is empty")
