class CarRentalService:
    def __init__(self):
        """Initialize the car rental service with an empty dictionary of cars."""
        self.cars = {}

    def add_car(self, car_id, price_per_day):
        """Add a new car to the rental service with a unique identifier and a rental price per day."""
        if car_id in self.cars:
            print(f"Car with ID {car_id} already exists.")
        else:
            self.cars[car_id] = (price_per_day, False)
            print(f"Car with ID {car_id} added successfully.")

    def rent_car(self, car_id, days):
        """Rent a car for a specified number of days and return the total cost or an error message."""
        if car_id not in self.cars:
            return "Car not found."
        price_per_day, is_rented = self.cars[car_id]
        if is_rented:
            return "Car is already rented out."
        else:
            self.cars[car_id] = (price_per_day, True)
            total_cost = price_per_day * days
            return f"Car {car_id} rented successfully for {days} days. Total cost: ${total_cost}."

    def return_car(self, car_id):
        """Return a rented car and mark it as available or return an error message."""
        if car_id not in self.cars:
            return "Car not found."
        price_per_day, is_rented = self.cars[car_id]
        if not is_rented:
            return "This car was not rented."
        else:
            self.cars[car_id] = (price_per_day, False)
            return f"Car {car_id} returned successfully."

    def check_availability(self, car_id):
        """Check if a car is available for rent and return True or False."""
        if car_id not in self.cars:
            return "Car not found."
        _, is_rented = self.cars[car_id]
        return not is_rented


