def length_of_longest_increasing_subsequence(nums):
    """
    Determine the length of the longest increasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

