def encode_to_rot13(text):
    """
    Encodes the given string using the ROT13 cipher.

    Parameters:
    text (str): The string to be encoded.

    Returns:
    str: The ROT13 encoded string.
    """
    def rot13_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 13) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 13) % 26 + ord('A'))
        else:
            return c

    return ''.join(rot13_char(c) for c in text)

