def deep_clone(obj):
    """
    Recursively clones a JavaScript-like object, preserving the structure and values of nested objects and arrays.

    :param obj: The object to be cloned.
    :return: A deep clone of the input object.
    """
    if isinstance(obj, dict):
        return {key: deep_clone(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [deep_clone(element) for element in obj]
    else:
        return obj

