class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if data else 0

    def __add__(self, other):
        """
        Add two matrices of the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added.")
        return Matrix([[a + b for a, b in zip(row1, row2)] for row1, row2 in zip(self.data, other.data)])

    def __sub__(self, other):
        """
        Subtract two matrices of the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be subtracted.")
        return Matrix([[a - b for a, b in zip(row1, row2)] for row1, row2 in zip(self.data, other.data)])

    def __mul__(self, other):
        """
        Multiply two matrices where the number of columns in the first matrix
        equals the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must equal the number of rows in the second matrix.")

        result = [[0 for _ in range(other.cols)] for _ in range(self.rows)]

        for i in range(self.rows):
            for j in range(other.cols):
                for k in range(self.cols):
                    result[i][j] += self.data[i][k] * other.data[k][j]
        return Matrix(result)

    def __str__(self):
        """
        Return a string representation of the matrix.
        """
        return '\n'.join(['\t'.join(map(str, r)) for r in self.data])
