class TextEditor:

    def __init__(self):
        self.text = ""

    def insert_text(self, position: int, text: str) -> None:
        """ 
        Inserts text at a specific position in the text editor. 
        """
        if position > len(self.text):
            raise ValueError("Error: position out of range.")
        self.text = self.text[:position] + text + self.text[position:]

    def delete_text(self, position: int, length: int) -> None:
        """
        Deletes a specified number of characters from a specific position in the text editor. 
        """
        if position + length > len(self.text):
            raise ValueError("Error: position + length out of range.")
        self.text = self.text[:position] + self.text[position + length:]

    def display_text(self) -> None:
        """
        Displays the current text in the text editor.
        """
        print(self.text)


def main():
    text_editor = TextEditor()
    operations = [
        "I 0 Hello, World!",
        "I 13 CS",
        "D 7 5",
        "P"
    ]

    for operation in operations:
        command, *args = operation.split()
        if command == 'I':
            position, text = int(args[0]), args[1]
            text_editor.insert_text(position, text)
        elif command == 'D':
            position, length = int(args[0]), int(args[1])
            text_editor.delete_text(position, length)
        elif command == 'P':
            text_editor.display_text()


