import json

def print_values_from_key(json_filename, key):
    """
    Reads a JSON file and prints all values associated with a specific key.

    Parameters:
    json_filename (str): The name of the JSON file.
    key (str): The key whose values need to be found.
    """
    try:
        with open(json_filename, 'r') as file:
            data = json.load(file)
    except FileNotFoundError:
        print(f"File {json_filename} not found.")
        return
    except json.JSONDecodeError:
        print(f"Error decoding JSON from file {json_filename}.")
        return

    def find_values(data, key):
        """
        Recursively finds and prints all values of a specific key in a nested dictionary or list.

        Parameters:
        data (dict or list): The data structure to search within.
        key (str): The key to search for.
        """
        if isinstance(data, dict):
            for k, v in data.items():
                if k == key:
                    print(v)
                else:
                    find_values(v, key)
        elif isinstance(data, list):
