from collections import defaultdict

def generate_family_tree(data, root_name):
    """
    Generates a JSON file representing a family tree based on parent-child relationships.

    Parameters:
    - data: List of tuples, where each tuple contains a child's name and their parent's name.
    - root_name: String representing the root of the family tree.

    Output:
    - A JSON file named 'family_tree.json' with the family tree structure.
    """
    def add_child(tree, parent, child):
        if parent not in tree:
            tree[parent] = {}
        if child not in tree[parent]:
            tree[parent][child] = {}

    family_tree = defaultdict(dict)

    for child, parent in data:
        add_child(family_tree, parent, child)

    all_children = {child for _, children in family_tree.items() for child in children}
    root = [person for person in family_tree.keys() if person not in all_children]

    root = root_name if root_name else root[0] if root else None

    with open('family_tree.json', 'w', encoding='utf-8') as f:
        json.dump(family_tree[root], f, ensure_ascii=False, indent=4)
