def longest_palindrome(s: str) -> str:
    """
    Finds the longest palindromic subsequence in the given string.
    If there are multiple subsequences of the same maximum length,
    returns the lexicographically smallest one.

    :param s: Input string
    :return: Longest palindromic subsequence
    """
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    n = len(s)
    if n == 0:
        return ""

    dp = [["" for _ in range(n)] for _ in range(n)]

    for i in range(n):
        dp[i][i] = s[i]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = s[i] + dp[i + 1][j - 1] + s[j]
            else:
                if len(dp[i + 1][j]) > len(dp[i][j - 1]):
                    dp[i][j] = dp[i + 1][j]
                elif len(dp[i + 1][j]) == len(dp[i][j - 1]):
                    dp[i][j] = min(dp[i + 1][j], dp[i][j - 1])
                else:
                    dp[i][j] = dp[i][j - 1]

    return dp[0][n - 1]
