def count_unique_substrings_with_two_digits(s: str) -> int:
    """
    Counts the number of unique substrings of the given string `s` that contain exactly two distinct digits.

    :param s: A string consisting of digits and lowercase letters.
    :return: The number of unique substrings with exactly two distinct digits.
    """
    seen = set()

    for i in range(len(s)):
        digits_seen = set()
        substring = ""
        for j in range(i, len(s)):
            substring += s[j]

            if s[j].isdigit():
                digits_seen.add(s[j])
                if len(digits_seen) > 2:
                    break
            if len(digits_seen) == 2:
                seen.add(substring)

    return len(seen)
