class Stack:
    def __init__(self):
        self.items = []

    def push(self, x):
        """Adds an element x to the top of the stack."""
        self.items.append(x)

    def pop(self):
        """Removes the top element from the stack and returns it. Returns -1 if the stack is empty."""
        if not self.empty():
            return self.items.pop()
        return -1

    def peek(self):
        """Returns the top element of the stack without removing it. Returns -1 if the stack is empty."""
        if not self.empty():
            return self.items[-1]
        return -1

    def empty(self):
        """Returns True if the stack is empty, otherwise returns False."""
        return len(self.items) == 0

