import json

def find_field_in_json(data, target_field):
    """
    Recursively searches for a target field in a nested JSON structure.

    :param data: The JSON data, which can be a dictionary or a list.
    :param target_field: The field name to search for.
    :return: The value associated with the target field, or None if not found.
    """
    if isinstance(data, dict):
        for key, value in data.items():
            if key == target_field:
                return value
            elif isinstance(value, (dict, list)):
                result = find_field_in_json(value, target_field)
                if result is not None:
                    return result
    elif isinstance(data, list):
        for item in data:
            result = find_field_in_json(item, target_field)
            if result is not None:
                return result
    return None

def read_json_field(file_path, field_name):
    """
    Reads a JSON file and returns the value associated with a specified field.

    :param file_path: The path to the JSON file.
    :param field_name: The field name to search for.
    :return: The value associated with the field, or None if not found.
    """
    with open(file_path, 'r') as file:
        json_data = json.load(file)
        return find_field_in_json(json_data, field_name)
