class GameBoard:
    def __init__(self, width, height):
        """Initialize a 2D game board of size width x height."""
        self.width = width
        self.height = height
        self.board = [[None for _ in range(width)] for __ in range(height)]

    def add_piece(self, piece, x, y):
        """Add a game piece to the board at position (x, y). Raise ValueError if position is out of bounds."""
        if 0 <= x < self.width and 0 <= y < self.height:
            self.board[y][x] = piece
        else:
            raise ValueError("Position out of bounds")

    def move_piece(self, piece, x, y, new_x, new_y):
        """Move a game piece from position (x, y) to position (new_x, new_y). Raise ValueError if positions are out of bounds or if no piece is found at (x, y)."""
        if 0 <= x < self.width and 0 <= y < self.height and 0 <= new_x < self.width and 0 <= new_y < self.height:
            if self.board[y][x] == piece:
                self.board[y][x] = None
                self.board[new_y][new_x] = piece
            else:
                raise ValueError("No piece found at the given position")
        else:
            raise ValueError("Position out of bounds")

    def is_piece_at(self, x, y):
        """Check if there is a piece at position (x, y). Raise ValueError if position is out of bounds."""
        if 0 <= x < self.width and 0 <= y < self.height:
            return self.board[y][x] is not None
        else:
            raise ValueError("Position out of bounds")
