class MinStack:
    def __init__(self):
        # Initialize the main stack and an auxiliary stack to keep track of minimum elements
        self.stack = []
        self.min_stack = []

    def push(self, x):
        """Push the element x onto the stack."""
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        """Remove the top element from the stack and return it. Return None if the stack is empty."""
        if self.stack:
            x = self.stack.pop()
            if x == self.min_stack[-1]:
                self.min_stack.pop()
            return x
        return None

    def peek(self):
        """Return the top element of the stack without removing it. Return None if the stack is empty."""
        if self.stack:
            return self.stack[-1]
        return None

    def get_min(self):
        """Return the minimum element in the stack. Return None if the stack is empty."""
        if self.min_stack:
            return self.min_stack[-1]
        return None
