class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class BinarySearchTree:
    def __init__(self, values):
        """
        Initializes the Binary Search Tree with a list of values.
        """
        self.root = None
        for value in values:
            self.insert(value)

    def insert(self, value):
        """
        Inserts a new value into the BST.
        """
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert(self.root, value)

    def _insert(self, node, value):
        """
        Helper method to insert a new value into the BST recursively.
        """
        if value < node.val:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert(node.right, value)

    def inorder_traversal(self, node):
        """
        Returns the in-order traversal of the BST as a generator.
        """
        if node:
            yield from self.inorder_traversal(node.left)
            yield node.val
            yield from self.inorder_traversal(node.right)

