app = Flask(__name__)

# Sample data structure to store books in memory (in a real application this would be a database)
books = [
    {"id": 1, "title": "1984", "author": "George Orwell", "isbn": "978-0451524935"},
    {"id": 2, "title": "To Kill a Mockingbird", "author": "Harper Lee", "isbn": "978-0060935467"},
]

def find_book(book_id):
    """Helper function to find a book by ID."""
    return next((book for book in books if book['id'] == book_id), None)

@app.route('/books', methods=['POST'])
def create_book():
    """Create a new book."""
    if not request.json or 'title' not in request.json or 'author' not in request.json or 'isbn' not in request.json:
        abort(400)  # Bad request
    book_id = books[-1]['id'] + 1 if books else 1  # Auto-increment ID
    new_book = {
        "id": book_id,
        "title": request.json['title'],
        "author": request.json['author'],
        "isbn": request.json['isbn']
    }
    books.append(new_book)
    return jsonify(new_book), 201  # Created

@app.route('/books', methods=['GET'])
def get_books():
    """Retrieve a list of all books."""
    return jsonify(books)

@app.route('/books/<int:book_id>', methods=['GET'])
def get_book(book_id):
    """Retrieve a book by its ID."""
    book = find_book(book_id)
    if book is None:
        abort(404)  # Not Found
    return jsonify(book)

@app.route('/books/<int:book_id>', methods=['PUT'])
def update_book(book_id):
    """Update a book by its ID."""
    book = find_book(book_id)
    if book is None:
        abort(404)  # Not Found
    if not request.json:
        abort(400)  # Bad request
    book['title'] = request.json.get('title', book['title'])
    book['author'] = request.json.get('author', book['author'])
    book['isbn'] = request.json.get('isbn', book['isbn'])
    return jsonify(book)

@app.route('/books/<int:book_id>', methods=['DELETE'])
def delete_book(book_id):
    """Delete a book by its ID."""
    book = find_book(book_id)
    if book is None:
        abort(404)  # Not Found
    books.remove(book)
    return jsonify({'result': True})

@app.errorhandler(404)
def not_found(error):
    """Error handler for 404 (Not Found)."""
    return jsonify({'error': 'Not found'}), 404

@app.errorhandler(400)
def bad_request(error):
    """Error handler for 400 (Bad Request)."""
    return jsonify({'error': 'Bad request'}), 400

if __name__ == '__main__':
    app.run(debug=True)
```

