def topological_sort_dfs(graph):
    """
    Returns a list of nodes in topological order using depth-first search.

    :param graph: A dictionary representing a directed acyclic graph (DAG) as an adjacency list.
    :return: A list of nodes in topological order.
    """
    visited = set()
    stack = []

    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)
        stack.append(node)

    for node in graph:
        if node not in visited:
            dfs(node)

    return stack[::-1]
