def classify_languages(languages):
    """
    Classifies a list of programming languages into Functional, Imperative, and Object-Oriented categories.

    Parameters:
    languages (list of str): A list of programming language names.

    Returns:
    dict: A dictionary with categories as keys and lists of languages as values.
    """
    functional = {'Haskell', 'Erlang'}
    imperative = {'C++'}
    object_oriented = {'Python', 'Java', 'Ruby'}

    categorized_languages = {'Functional': [], 'Imperative': [], 'Object-Oriented': []}

    for language in languages:
        if language in functional:
            categorized_languages['Functional'].append(language)
        elif language in imperative:
            categorized_languages['Imperative'].append(language)
        elif language in object_oriented:
            categorized_languages['Object-Oriented'].append(language)

    return categorized_languages

