def harmonic_sum(n):
    """
    Calculate the sum of the harmonic series up to the nth term.

    Parameters:
    n (int): The number of terms in the harmonic series to sum up.

    Returns:
    float: The sum of the harmonic series up to the nth term.
    """
    if n < 1:
        return 0
    elif n == 1:
        return 1
    else:
        return 1 / n + (harmonic_sum(n - 1))
