def count_frequencies(lst):
    """
    Returns a list of tuples, where each tuple contains an integer from the list and its frequency.

    :param lst: List of integers
    :return: List of tuples (integer, frequency)
    """
    frequency_dict = {}
    for item in lst:
        if item in frequency_dict:
            frequency_dict[item] += 1
        else:
            frequency_dict[item] = 1
    return list(frequency_dict.items())

