import heapq

class MinMaxHeap:
    def __init__(self):
        self.min_heap = []
        self.max_heap = []

    def insert(self, num):
        """Insert a number into the data structure."""
        heapq.heappush(self.min_heap, num)
        heapq.heappush(self.max_heap, -num)

    def get_min(self):
        """Retrieve the minimum number in the data structure."""
        if self.min_heap:
            return self.min_heap[0]

    def get_max(self):
        """Retrieve the maximum number in the data structure."""
        if self.max_heap:
            return -self.max_heap[0]
