def caesar_cipher(text, shift):
    """
    Encodes a given text using the Caesar cipher technique with a specified shift value.

    Parameters:
    text (str): The string to be encoded.
    shift (int): The shift value for the cipher.

    Returns:
    str: The encoded string.
    """
    def shift_char(c, shift, start, end):
        if start <= ord(c) <= end:
            return chr(start + (ord(c) - start + shift) % 26)
        else:
            return c

    result = []
    for char in text:
        if 'a' <= char <= 'z':
            result.append(shift_char(char, shift, ord('a'), ord('z')))
        elif 'A' <= char <= 'Z':
            result.append(shift_char(char, shift, ord('A'), ord('Z')))
        else:
            result.append(char)

    return ''.join(result)

