import json
import sys

def extract_info(json_data, key):
    """
    Recursively search for values by key in a nested JSON structure.

    :param json_data: The JSON data to search through.
    :param key: The key to search for.
    :yield: Values associated with the specified key.
    """
    if isinstance(json_data, dict):
        for k, v in json_data.items():
            if k == key:
                yield v
            else:
                yield from extract_info(v, key)
    elif isinstance(json_data, list):
        for item in json_data:
            yield from extract_info(item, key)

def main(json_file_path, key):
    """
    Main function to parse JSON file and extract information.

    :param json_file_path: Path to the JSON file.
    :param key: The key to search for in the JSON file.
    """
    with open(json_file_path, 'r') as file:
        data = json.load(file)

    results = extract_info(data, key)
    for result in results:
        print(result)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python script.py <json_file_path> <key>")
    else:
        json_file_path = sys.argv[1]
        key = sys.argv[2]
        main(json_file_path, key)
