import csv

def calculate_average_salaries(csv_file_path):
    """
    Reads a CSV file containing employee data and calculates the average salary for each department.

    Parameters:
    csv_file_path (str): The path to the CSV file.

    Returns:
    dict: A dictionary with department names as keys and their corresponding average salaries as values.
    """
    department_salaries = {}
    department_count = {}

    try:
        with open(csv_file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            for row in reader:
                department = row['Department'].strip()
                salary = row['Salary'].strip()

                if department and salary:
                    try:
                        salary = float(salary)
                        if department not in department_salaries:
                            department_salaries[department] = 0
                            department_count[department] = 0
                        department_salaries[department] += salary
                        department_count[department] += 1
                    except ValueError:
                        print(f"Warning: Invalid salary data '{salary}' found for employee '{row['Name']}' in department '{department}'. Skipping this entry.")
        average_salaries = {dept: department_salaries[dept] / department_count[dept] for dept in department_salaries}
        return average_salaries
    except FileNotFoundError:
        print(f"Error: The file {csv_file_path} does not exist.")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}
