class BankAccount:
    def __init__(self, owner, balance=0.0):
        """Initialize the bank account with an owner and an optional initial balance."""
        self.owner = owner
        self.balance = balance
        self.transaction_history = []

    def deposit(self, amount):
        """Deposit the specified amount into the account if the amount is positive."""
        if amount > 0:
            self.balance += amount
            self.transaction_history.append(f"Deposited: {amount}")

    def withdraw(self, amount):
        """Withdraw the specified amount from the account if the amount is positive and sufficient funds are available."""
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            self.transaction_history.append(f"Withdrawn: {amount}")

    def display_balance(self):
        """Return the current balance of the account."""
        return self.balance

    def show_transaction_history(self):
        """Return the transaction history of the account."""
        return self.transaction_history
