def calculate_area(radius):
    """
    Calculate the area of a circle given its radius.

    Parameters:
    radius (str or float): The radius of the circle.

    Returns:
    float or str: The area of the circle if the input is valid, 
                  or an error message if the input is invalid.
    """
    try:
        radius = float(radius)
        if radius < 0:
            raise ValueError("Radius cannot be negative")
        return 3.14 * radius * radius
    except ValueError as e:
        return str(e)
    except TypeError:
        return "Invalid input type. Please provide a number for the radius."
