class TextAdventureGame:
    def __init__(self):
        """Initialize the game state."""
        self.current_location = "start"
        self.inventory = []
        self.game_over = False
        self.locations = {
            "start": {
                "description": "You are in a dark forest. Paths lead to the north and east.",
                "north": "clearing",
                "east": "cave",
                "items": ["torch"],
            },
            "clearing": {
                "description": "You are in a sunny clearing. Paths lead to the south.",
                "south": "start",
                "items": ["flower"],
            },
            "cave": {
                "description": "You are in a dark, damp cave. Paths lead to the west and deeper inside.",
                "west": "start",
                "inside": "treasure",
                "items": ["rock"],
            },
            "treasure": {
                "description": "Congratulations, you have found the treasure! You win!",
                "items": None,
                "end_game": True,
            },
        }

    def display_introduction(self):
        """Display the game introduction."""
        print("Welcome to the Text Adventure Game!")
        print("You find yourself in a dark forest. Your goal is to find the treasure.")
        print("Type 'help' to see the available commands.\n")
        self.display_location()

    def display_location(self):
        """Display the current location's description and items."""
        location = self.locations[self.current_location]
        print(location["description"])
        if location["items"]:
            print("You see: " + ", ".join(location["items"]))
        else:
            print("There are no items here.")

    def handle_input(self):
        """Handle user input and update the game state."""
        while not self.game_over:
            command = input("\nWhat do you do? ").strip().lower()
            if command in ("help", "h"):
                print("Available commands are: go [direction], take [item], inventory, look, quit.")
            elif command.startswith("go "):
                direction = command.split(" ", 1)[1]
                self.move_to_direction(direction)
            elif command.startswith("take "):
                item = command.split(" ", 1)[1]
                self.take_item(item)
            elif command == "inventory":
                self.display_inventory()
            elif command == "look":
                self.display_location()
            elif command == "quit":
                print("Thanks for playing! Goodbye.")
                self.game_over = True
            else:
                print("Invalid command. Type 'help' for a list of commands.")

    def move_to_direction(self, direction):
        """Move to a new location if possible."""
        location = self.locations[self.current_location]
        if direction in location:
            self.current_location = location[direction]
            if self.current_location == "treasure":
                self.game_over = True
            self.display_location()
        else:
            print("You can't go that way.")

    def take_item(self, item):
        """Pick up an item if it's in the current location."""
        location = self.locations[self.current_location]
        if item in location["items"]:
            self.inventory.append(item)
            location["items"].remove(item)
            print(f"You picked up the {item}.")
            if not location["items"]:
                print("There are no more items here.")
        else:
            print(f"There is no {item} here.")

    def display_inventory(self):
        """Display the player's inventory."""
        if self.inventory:
            print("Inventory: " + ", ".join(self.inventory))
        else:
            print("Your inventory is empty.")

# Example usage
game = TextAdventureGame()
game.display_introduction()
game.handle_input()
