class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def inorder_traversal(root):
    """
    Perform an in-order traversal of a binary tree and return the values of the nodes in a list.

    :param root: TreeNode, the root of the binary tree
    :return: List[int], the values of the nodes in in-order traversal
    """
    def traverse(node):
        if not node:
            return []
        return traverse(node.left) + [node.value] + traverse(node.right)

    return traverse(root)
