def count_common_substrings_of_length_three(str1, str2):
    """
    Returns the number of distinct common substrings of length 3 between two strings.

    :param str1: First input string
    :param str2: Second input string
    :return: Number of distinct common substrings of length 3
    """
    if len(str1) < 3 or len(str2) < 3:
        return 0

    substrings_str1 = {str1[i:i+3] for i in range(len(str1) - 2)}
    substrings_str2 = {str2[i:i+3] for i in range(len(str2) - 2)}

    common_substrings = substrings_str1.intersection(substrings_str2)

    return len(common_substrings)
