class SimpleHashTable:
    def __init__(self, size=10):
        """Initialize the hash table with a given size."""
        self.size = size
        self.table = [[] for _ in range(self.size)]

    def _hash_function(self, key):
        """Simple hash function that converts key to an index."""
        return hash(key) % self.size

    def insert(self, key, value):
        """Insert a key-value pair into the hash table."""
        index = self._hash_function(key)
        for pair in self.table[index]:
            if pair[0] == key:
                pair[1] = value
                return
        self.table[index].append([key, value])

    def delete(self, key):
        """Delete a key from the hash table."""
        index = self._hash_function(key)
        for i, pair in enumerate(self.table[index]):
            if pair[0] == key:
                del self.table[index][i]
                return

    def retrieve(self, key):
        """Retrieve the value associated with a key from the hash table."""
        index = self._hash_function(key)
        for pair in self.table[index]:
            if pair[0] == key:
                return pair[1]
        return None

# Example usage
hash_table = SimpleHashTable()
hash_table.insert('apple', 10)
hash_table.insert('banana', 20)
print(hash_table.retrieve('apple'))  # Output: 10
hash_table.delete('banana')
print(hash_table.retrieve('banana'))  # Output: None
```

