def trap(heights):
    """
    Calculate the total amount of water trapped between the buildings after a rainstorm.

    :param heights: List[int] - An array of non-negative integers representing the heights of buildings.
    :return: int - The total amount of water trapped.
    """
    if not heights or len(heights) < 3:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = 0, 0
    water_trapped = 0

    while left < right:
        if heights[left] <= heights[right]:
            if heights[left] >= left_max:
                left_max = heights[left]
            else:
                water_trapped += left_max - heights[left]
            left += 1
        else:
            if heights[right] >= right_max:
                right_max = heights[right]
            else:
                water_trapped += right_max - heights[right]
            right -= 1

    return water_trapped

