class Polynomial:
    """ Class to represent a polynomial """
    def __init__(self, coefficient_list):
        """
        Create a polynomial from a list of coefficients. The i-th element of the list
        represents the coefficient for the x^i term.
        """
        self.coeffs = coefficient_list

    def __add__(self, other):
        """
        Add two polynomials.

        :param other: Another Polynomial instance
        :return: A new Polynomial instance representing the sum
        """
        result = [0] * max(len(self.coeffs), len(other.coeffs))
        for i in range(len(self.coeffs)):
            result[i] += self.coeffs[i]
        for i in range(len(other.coeffs)):
            result[i] += other.coeffs[i]
        return Polynomial(result)

    def __sub__(self, other):
        """
        Subtract two polynomials.

        :param other: Another Polynomial instance
        :return: A new Polynomial instance representing the difference
        """
        result = [0] * max(len(self.coeffs), len(other.coeffs))
        for i in range(len(self.coeffs)):
            result[i] += self.coeffs[i]
        for i in range(len(other.coeffs)):
            result[i] -= other.coeffs[i]
        return Polynomial(result)

    def __mul__(self, other):
        """
        Multiply two polynomials.

        :param other: Another Polynomial instance
        :return: A new Polynomial instance representing the product
        """
        result = [0] * (len(self.coeffs) + len(other.coeffs) - 1)
        for i in range(len(self.coeffs)):
            for j in range(len(other.coeffs)):
                result[i + j] += self.coeffs[i] * other.coeffs[j]
        return Polynomial(result)

    def evaluate(self, x):
        """
        Evaluate the polynomial at a given point x.

        :param x: The point at which to evaluate the polynomial
        :return: The value of the polynomial at x
        """
        return sum(coeff * (x ** power) for power, coeff in enumerate(self.coeffs))

    def __repr__(self):
        """
        Returns a Haskell-like string representation of the polynomial.

        :return: A string representing the polynomial
        """
        terms = []
        for power, coeff in enumerate(self.coeffs):
            if coeff == 0:
                continue
            term = f"{coeff}{'x' if power > 0 else ''}"
            if power > 1:
                term += f"^{power}"
            terms.append(term)
        return " + ".join(terms) or "0"
