    associated with that key across all dictionaries in the input list.

    :param dict_list: List of dictionaries with comparable values
    :return: List of tuples (key, max_value)
    """
    max_values = {}
    for dictionary in dict_list:
        for key, value in dictionary.items():
            if key not in max_values:
                max_values[key] = value
            elif value > max_values[key]:
                max_values[key] = value
    return list(max_values.items())

# Example usage:
dict_list = [{'a': 1, 'b': 2}, {'a': 3, 'b': 1}, {'a': 2, 'c': 4}]
