    """
    Retrieve a specific task by its ID.
    """
    task = next((task for task in tasks if task['id'] == task_id), None)
    if task is None:
        return jsonify({'error': 'Not Found', 'message': 'Task not found'}), 404
    return jsonify(task), 200

