    if task is None:
        return jsonify({'error': 'Not Found', 'message': 'Task not found'}), 404

    data = request.json
    if 'title' in data:
        task['title'] = data['title']
    if 'description' in data:
        task['description'] = data['description']
    if 'due_date' in data:
        try:
            task['due_date'] = datetime.strptime(data['due_date'], '%Y-%m-%d').strftime('%Y-%m-%d')
        except ValueError:
            return jsonify({'error': 'Bad Request', 'message': 'Invalid date format, use YYYY-MM-DD'}), 400

    return jsonify(task), 200

@app.route('/tasks/<int:task_id>', methods=['DELETE'])
def delete_task(task_id):
    """
    Delete a specific task by its ID.
    """
    global tasks
    task = next((t for t in tasks if t['id'] == task_id), None)
    if task is None:
        return jsonify({'error': 'Not Found', 'message': 'Task not found'}), 404

    tasks = [t for t in tasks if t['id'] != task_id]
