def get_leaf_values(json_obj):
    """
    Recursively traverses a JSON object and returns a list of all leaf node values.

    :param json_obj: A JSON object represented as a Python dictionary or list.
    :return: A list of all leaf node values.
    """
    leaf_values = []

    def traverse(data):
        if isinstance(data, dict):
            for value in data.values():
                traverse(value)
        elif isinstance(data, list):
            for item in data:
                traverse(item)
        else:
            leaf_values.append(data)

