def is_bst(tree):
    """
    Determines if a given binary tree is a binary search tree (BST).

    :param tree: A list of tuples representing the binary tree.
                 Each tuple contains the value of the node and its left and right children.
    :return: True if the tree is a BST, False otherwise.
    """
    def validate(node, low=float('-inf'), high=float('inf')):
        if not node:
            return True
        value, left, right = node

        if not (low < value < high):
            return False

        if not validate(left, low, value):
            return False
        if not validate(right, value, high):
            return False

        return True

    return validate(tree[0])
