def merge_and_deduplicate(list1, list2):
    """
    Merges two sorted lists into a single sorted list without duplicates.

    Parameters:
    list1 (List[int]): The first sorted list of integers.
    list2 (List[int]): The second sorted list of integers.

    Returns:
    List[int]: A new sorted list containing all unique elements from both input lists.
    """
    i, j = 0, 0
    merged_list = []

    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            if not merged_list or merged_list[-1] != list1[i]:
                merged_list.append(list1[i])
            i += 1
        elif list1[i] > list2[j]:
            if not merged_list or merged_list[-1] != list2[j]:
                merged_list.append(list2[j])
            j += 1
        else:
            if not merged_list or merged_list[-1] != list1[i]:
                merged_list.append(list1[i])
            i += 1
            j += 1

    while i < len(list1):
        if not merged_list or merged_list[-1] != list1[i]:
            merged_list.append(list1[i])
        i += 1

    while j < len(list2):
        if not merged_list or merged_list[-1] != list2[j]:
            merged_list.append(list2[j])
        j += 1

    return merged_list

# Example usage:
print(merge_and_deduplicate([1, 2, 4, 5], [2, 3, 5, 6]))  # Output: [1, 2, 3, 4, 5, 6]
print(merge_and_deduplicate([10, 20, 30, 40], [5, 15, 25, 35, 40, 45]))  # Output: [5, 10, 15, 20, 25, 30, 35, 40, 45]
