import json

def flatten_json(y):
    """
    Recursively flattens a nested dictionary into a flat dictionary with dot-separated keys.

    :param y: The nested dictionary to flatten.
    :return: A flat dictionary with dot-separated keys.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

def json_to_flat_dict(json_string):
    """
    Converts a JSON string representing a nested dictionary into a flat dictionary with dot-separated keys.

    :param json_string: The JSON string to convert.
    :return: A flat dictionary with dot-separated keys.
    """
    data = json.loads(json_string)
    return flatten_json(data)

