def is_valid_brackets(sequence: str) -> bool:
    """
    Determines if the given string of brackets is valid.

    :param sequence: A string containing only the characters '(', ')', '[', ']', '{', and '}'.
    :return: True if the string is a valid sequence of brackets, otherwise False.
    """
    pairs = {'(': ')', '[': ']', '{': '}'}
    stack = []

    for char in sequence:
        if char in pairs:
            stack.append(char)
        else:
            if not stack or pairs[stack.pop()] != char:
                return False

    return not stack

