class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a new value into the binary search tree."""
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert a value recursively."""
        if value < node.value:
            if node.left:
                self._insert_recursively(node.left, value)
            else:
                node.left = TreeNode(value)
        else:
            if node.right:
                self._insert_recursively(node.right, value)
            else:
                node.right = TreeNode(value)

    def inorder_traversal(self):
        """Returns a list of values in the tree in in-order sequence."""
        elements = []
        self._inorder_recursively(self.root, elements)
        return elements

    def _inorder_recursively(self, node, elements):
        """Helper method to perform in-order traversal recursively."""
        if node:
            self._inorder_recursively(node.left, elements)
            elements.append(node.value)
            self._inorder_recursively(node.right, elements)

    def find_height(self):
        """Returns the height of the tree."""
        return self._find_height_recursively(self.root)

    def _find_height_recursively(self, node):
        """Helper method to find the height of the tree recursively."""
        if not node:
            return 0
        left_height = self._find_height_recursively(node.left)
        right_height = self._find_height_recursively(node.right)
        return 1 + max(left_height, right_height)
