def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def count_distinct_primes(numbers):
    """Count the number of distinct prime numbers in a list."""
    prime_set = set()
    for number in numbers:
        if is_prime(number):
            prime_set.add(number)
    return len(prime_set)

