class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.keys = [None] * self.size
        self.values = [None] * self.size

    def hash_function(self, key):
        """Compute an index from the given key using modulo operation."""
        return key % self.size

    def insert(self, key, value):
        """Inserts a (key, value) pair into the hash table using linear probing."""
        slot = self.hash_function(key)
        start_slot = slot
        while self.keys[slot] is not None:
            if self.keys[slot] == key:
                self.values[slot] = value
                return "Inserted"
            slot = (slot + 1) % self.size
            if slot == start_slot:
                raise Exception("Hash table is full")
        self.keys[slot] = key
        self.values[slot] = value
        return "Inserted"

    def search(self, key):
        """Search for a value by key in the hash table using linear probing."""
        slot = self.hash_function(key)
        start_slot = slot
        while self.keys[slot] is not None:
            if self.keys[slot] == key:
                return self.values[slot]
            slot = (slot + 1) % self.size
            if slot == start_slot:
                break
        raise KeyError("Key not found in hash table")

    def delete(self, key):
        """Deletes a (key, value) pair from the hash table using linear probing."""
        slot = self.hash_function(key)
        start_slot = slot
        while self.keys[slot] is not None:
            if self.keys[slot] == key:
                self.keys[slot] = None
                self.values[slot] = None
                return "Deleted"
            slot = (slot + 1) % self.size
            if slot == start_slot:
                break
        raise KeyError("Key not found in hash table")

# Sample usage:
if __name__ == "__main__":
    ht = HashTable()
    operations = [
        "insert 10 ten",
        "insert 21 twenty-one",
        "insert 34 thirty-four",
        "search 21",
        "delete 21",
        "search 21"
    ]
    for operation in operations:
        parts = operation.split()
        if parts[0] == "insert":
            print(ht.insert(int(parts[1]), parts[2]))
        elif parts[0] == "search":
            try:
                print(ht.search(int(parts[1])))
            except KeyError as e:
                print(e)
        elif parts[0] == "delete":
            try:
                print(ht.delete(int(parts[1])))
            except KeyError as e:
                print(e)
