def convert_to_pig_latin(text):
    """
    Convert a given string into its Pig Latin representation.

    Parameters:
    text (str): A string of words separated by spaces.

    Returns:
    str: The Pig Latin translation of the input text.
    """
    vowels = "aeiou"
    words = text.split()
    pig_latin_words = []

    for word in words:
        if word[0].lower() in vowels:
            pig_latin_word = word + "ay"
        else:
            for i, letter in enumerate(word):
                if letter.lower() in vowels:
                    break
            pig_latin_word = word[i:] + word[:i] + "ay"

        pig_latin_words.append(pig_latin_word)

    return ' '.join(pig_latin_words)
