def flatten_json(y):
    """
    Flattens a nested dictionary or list into a single-level dictionary with dot-separated keys.

    :param y: A dictionary or list representing a JSON object.
    :return: A flattened dictionary with dot-separated keys.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out
