import json
import re

def extract_urls(json_file):
    """
    Parses a JSON file and extracts all URLs found in the string values of the JSON object.

    :param json_file: A string representing the path to a JSON file.
    :return: A list of strings, where each string is a URL found in the JSON file.
    """
    # Define a URL pattern regex
    url_pattern = re.compile(r'https?://[^\s]+')

    def find_urls_in_string(string):
        return url_pattern.findall(string)

    def find_urls_in_value(value):
        urls = []
        if isinstance(value, str):
            urls.extend(find_urls_in_string(value))
        elif isinstance(value, dict):
            for subvalue in value.values():
                urls.extend(find_urls_in_value(subvalue))
        elif isinstance(value, list):
            for item in value:
                urls.extend(find_urls_in_value(item))
        return urls

    with open(json_file, 'r') as file:
        data = json.load(file)

    return find_urls_in_value(data)
