def matrix_mult(A, B, mod):
    """
    Multiplies two 2x2 matrices A and B under modulo mod.
    """
    C = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            for k in range(2):
                C[i][j] = (C[i][j] + (A[i][k] * B[k][j]) % mod) % mod
    return C

def matrix_pow(M, n, mod):
    """
    Raises a 2x2 matrix M to the power of n under modulo mod using exponentiation by squaring.
    """
    result = [[1, 0], [0, 1]]  # Identity matrix
    base = M

    while n > 0:
        if n % 2 == 1:
            result = matrix_mult(result, base, mod)
        base = matrix_mult(base, base, mod)
        n //= 2

    return result

def fibonacci(n, mod=10**9+7):
    """
    Computes the nth Fibonacci number using matrix exponentiation under modulo mod.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 1

    F = [[1, 1], [1, 0]]  # Fibonacci transformation matrix
    result = matrix_pow(F, n-1, mod)

    return result[0][0]  # The top left cell of the matrix contains F(n)

# Example usage:
print(fibonacci(10))  # Outputs 55
print(fibonacci(1000))  # Outputs 434665576
