def swap_keys_values(input_dict):
    """
    Swaps the keys and values of the input dictionary.
    If multiple keys share the same value, they are grouped into a list.

    :param input_dict: Dictionary with string keys and integer values.
    :return: Dictionary with integer keys and list of string values.
