def is_balanced(s):
    """
    Determines if the parentheses in the string are balanced.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is balanced, otherwise False.
    """
    stack = []
    matching_bracket = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack
