class Library:
    def __init__(self):
        self.books = {}  # book_id: title
        self.checked_out_books = {}  # book_id: True if checked out

    def add_book(self, book_id, title):
        """Add a book to the library if it doesn't already exist."""
        if book_id not in self.books:
            self.books[book_id] = title
            self.checked_out_books[book_id] = False
            print(f"Book '{title}' with ID {book_id} added.")
        else:
            print(f"Book with ID {book_id} already exists.")

    def remove_book(self, book_id):
        """Remove a book from the library if it exists."""
        if book_id in self.books:
            title = self.books.pop(book_id)
            self.checked_out_books.pop(book_id)
            print(f"Book '{title}' with ID {book_id} removed.")
        else:
            print(f"Book with ID {book_id} does not exist.")

    def check_out_book(self, book_id):
        """Check out a book if it exists and is not already checked out."""
        if book_id in self.books and not self.checked_out_books[book_id]:
            self.checked_out_books[book_id] = True
            print(f"Book with ID {book_id} checked out.")
        elif book_id not in self.books:
            print(f"Book with ID {book_id} does not exist.")
        else:
            print(f"Book with ID {book_id} is already checked out.")

    def return_book(self, book_id):
        """Return a book if it exists and is currently checked out."""
        if book_id in self.books and self.checked_out_books[book_id]:
            self.checked_out_books[book_id] = False
            print(f"Book with ID {book_id} returned.")
        elif book_id not in self.books:
            print(f"Book with ID {book_id} does not exist.")
        else:
            print(f"Book with ID {book_id} is not checked out.")

    def list_books(self):
        """List all books in the library and their checkout status."""
        for book_id, title in self.books.items():
            status = "checked out" if self.checked_out_books[book_id] else "not checked out"
            print(f"ID {book_id}: {title} ({status})")

