def is_prime(n):
    """
    Check if a number is prime.

    :param n: Integer to check for primality.
    :return: True if n is prime, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    return all(n % i != 0 for i in range(3, int(n**0.5) + 1, 2))

def find_primes_in_range(start, end):
    """
    Find all prime numbers in the given range [start, end].

    :param start: Starting integer of the range.
    :param end: Ending integer of the range.
    :return: List of prime numbers within the range.
    """
    if start < 2:
        start = 2
    if start % 2 == 0:
        start += 1

    primes = [num for num in range(start, end + 1, 2) if is_prime(num)]

    if start == 2:
        primes.insert(0, 2)

    return primes
