    """
    Determines if the input string of parentheses is valid.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is valid, otherwise False.
    """
    matching = {")": "(", "}": "{", "]": "["}
    stack = []

    for char in s:
        if char in matching:
            top_element = stack.pop() if stack else '#'
            if matching[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack
