def longestPathDAG(adjList):
    """
    Finds the length of the longest path in a directed acyclic graph (DAG) represented as an adjacency list.

    Parameters:
    adjList (dict): A dictionary representing the graph where keys are nodes and values are lists of adjacent nodes.

    Returns:
    int: The length of the longest path in terms of the number of edges.
    """
    from collections import deque

    def topologicalSort():
        in_degree = {u: 0 for u in adjList}
        for u in adjList:
            for v in adjList[u]:
                in_degree[v] += 1
        queue = deque([u for u in adjList if in_degree[u] == 0])
        order = []
        while queue:
            u = queue.popleft()
            order.append(u)
            for v in adjList[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        return order

    order = topologicalSort()
    dp = {u: 0 for u in adjList}
    for u in order:
        for v in adjList[u]:
            dp[v] = max(dp[v], dp[u] + 1)
    return max(dp.values())
