class LibrarySystem:
    def __init__(self):
        """Initializes an empty library system."""
        self.books = {}

    def add_book(self, title, quantity=1):
        """Adds quantity copies of a book with title to the library."""
        if title in self.books:
            self.books[title] += quantity
        else:
            self.books[title] = quantity

    def remove_book(self, title, quantity=1):
        """Removes quantity copies of a book with title from the library. Raises ValueError if title does not exist or less than quantity."""
        if title not in self.books:
            raise ValueError(f"No book '{title}' in the library.")
        if self.books[title] < quantity:
            raise ValueError(f"Not enough copies of '{title}' in the library to remove {quantity}.")
        self.books[title] -= quantity
        if self.books[title] == 0:
            del self.books[title]

    def checkout_book(self, title):
        """Checks out one copy of a book with title from the library. Raises ValueError if no copies are available."""
        if title not in self.books or self.books[title] == 0:
            raise ValueError(f"No copies of '{title}' are available to checkout.")
        self.books[title] -= 1
        if self.books[title] == 0:
            del self.books[title]
