class SimpleTextEditor:
    def __init__(self):
        self.text = []  # Using list to store characters for efficient insertions and deletions
        self.cursor_pos = 0

    def insert_text(self, text):
        """
        Inserts the string `text` at the current cursor position.
        """
        for char in text:
            self.text.insert(self.cursor_pos, char)
            self.cursor_pos += 1

    def delete_char(self):
        """
        Deletes the character at the current cursor position, if the cursor is not at the beginning of the text.
        """
        if self.cursor_pos > 0:
            self.text.pop(self.cursor_pos - 1)
            self.cursor_pos -= 1

    def move_cursor_left(self):
        """
        Moves the cursor one position to the left, if possible.
        """
        if self.cursor_pos > 0:
            self.cursor_pos -= 1

    def move_cursor_right(self):
        """
        Moves the cursor one position to the right, if possible.
        """
        if self.cursor_pos < len(self.text):
            self.cursor_pos += 1

    def get_text(self):
        """
        Returns the current text as a string.
        """
        return ''.join(self.text)

    def get_cursor_position(self):
        """
        Returns the current position of the cursor.
        """
        return self.cursor_pos
