import json
import os

DATABASE_FILE = 'simple_db.json'

def load_db():
    """Load the database from the JSON file."""
    if os.path.exists(DATABASE_FILE):
        with open(DATABASE_FILE, 'r') as file:
            return json.load(file)
    return {}

def save_db(database):
    """Save the current state of the database to the JSON file."""
    with open(DATABASE_FILE, 'w') as file:
        json.dump(database, file, indent=4)

def add_record(database, key, data):
    """Add a new record to the database."""
    if key in database:
        print(f"Record with key '{key}' already exists.")
        return False
    database[key] = data
    save_db(database)
    print(f"Record with key '{key}' added.")
    return True

def view_record(database, key):
    """View a record from the database by key."""
    record = database.get(key)
    if record:
        print(f"Record with key '{key}': {record}")
    else:
        print(f"No record found with key '{key}'.")
    return record

def delete_record(database, key):
    """Delete a record from the database by key."""
    if key in database:
        del database[key]
        save_db(database)
        print(f"Record with key '{key}' deleted.")
        return True
    print(f"No record found with key '{key}'.")
    return False

def main():
    """Main function to run the simple database manager."""
    db = load_db()
    while True:
        action = input("Choose an action (add, view, delete, exit): ").strip().lower()
        key = None
        data = None

        if action in ['add', 'view', 'delete']:
            key = input("Enter the key for the record: ").strip()
            if action == 'add':
                data = input("Enter the data for the record (JSON format): ").strip()
                try:
                    data = json.loads(data)
                except json.JSONDecodeError:
                    print("Invalid JSON format. Please try again.")
                    continue

        if action == 'add':
            add_record(db, key, data)
        elif action == 'view':
            view_record(db, key)
        elif action == 'delete':
            delete_record(db, key)
        elif action == 'exit':
            print("Exiting the simple database manager.")
            break
        else:
            print("Invalid action. Please choose from 'add', 'view', 'delete', or 'exit'.")

if __name__ == '__main__':
    main()
