class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        """Inserts a word into the trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def _search_prefix(self, prefix):
        """Searches for the node corresponding to the end of the prefix."""
        node = self.root
        for char in prefix:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

    def search(self, word):
        """Returns True if the word is in the trie, otherwise False."""
        node = self._search_prefix(word)
        return node is not None and node.is_end_of_word

    def starts_with(self, prefix):
        """Returns True if there is any word in the trie that starts with the given prefix, otherwise False."""
        return self._search_prefix(prefix) is not None

    def get_words_with_prefix(self, prefix):
        """Returns a list of all words in the trie that start with the given prefix."""
        def _get_words_from_node(node, current_word):
            words = []
            if node.is_end_of_word:
                words.append(current_word)
            for char, child in node.children.items():
                words.extend(_get_words_from_node(child, current_word + char))
            return words

        node = self._search_prefix(prefix)
        if node is None:
            return []
        return _get_words_from_node(node, prefix)
