class Stack:
    def __init__(self):
        self.stack = []

    def push(self, element):
        """Add an element to the top of the stack."""
        self.stack.append(element)

    def pop(self):
        """Remove and return the top element of the stack. Raise IndexError if the stack is empty."""
        if not self.is_empty():
            return self.stack.pop()
        else:
            raise IndexError("pop from empty stack")

    def peek(self):
        """Return the top element of the stack without removing it. Raise IndexError if the stack is empty."""
        if not self.is_empty():
            return self.stack[-1]
        else:
            raise IndexError("peek from empty stack")

    def is_empty(self):
        """Return True if the stack is empty, otherwise False."""
        return len(self.stack) == 0

# Example usage:
if __name__ == "__main__":
    s = Stack()
    s.push(1)
    s.push(2)
    print(s.peek())  # Output: 2
    print(s.pop())   # Output: 2
    print(s.pop())   # Output: 1
    print(s.is_empty())  # Output: True
