def flatten_list(lst):
    """
    Flattens a nested list of arbitrary depth into a single list of integers.

    :param lst: List of integers and/or nested lists
    :return: A single flattened list of integers
    """
    def flatten(sublist):
        for item in sublist:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item
    return list(flatten(lst))
