def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(start, end):
    """Find the sum of all prime numbers in a given range [start, end]."""
    total = 0
    for num in range(start, end + 1):
        if is_prime(num):
            total += num
    return total

