def flatten_json(y):
    """
    Flattens a nested JSON object into a single-level dictionary with compound keys.

    :param y: A dictionary representing the JSON object to be flattened.
    :return: A dictionary with flattened keys and values.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '_')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '_')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

