def get_book(book_id):
    """
    Retrieve a book by its unique identifier.
    Returns a JSON object of the book if found, otherwise returns a 404 error.
    """
    book = next((book for book in books if book['id'] == book_id), None)
    if book is not None:
        return jsonify(book)
    else:
        abort(404, description="Book not found")

@app.route('/books', methods=['POST'])
def add_book():
    """
    Add a new book to the catalog.
    Expects a JSON request body with 'title' and 'author' fields.
    Returns a JSON object of the newly added book with a 201 status code.
    """
    if not request.json or 'title' not in request.json or 'author' not in request.json:
        abort(400, description="Invalid request: title and author are required")
    new_book_id = max(book['id'] for book in books) + 1 if books else 1
    new_book = {
        'id': new_book_id,
        'title': request.json['title'],
        'author': request.json['author']
    }
    books.append(new_book)
    return jsonify(new_book), 201

@app.route('/books/<int:book_id>', methods=['DELETE'])
def delete_book(book_id):
    """
    Delete a book from the catalog by its unique identifier.
    Returns a JSON object with 'result': true if the book was successfully deleted.
    """
    global books
    book = next((book for book in books if book['id'] == book_id), None)
    if book is None:
        abort(404, description="Book not found")

    books = [book for book in books if book['id'] != book_id]
    return jsonify({'result': True})

