def is_tree(graph):
    """
    Determines if the given graph is a tree.

    Args:
    graph (dict): A dictionary representing the graph where keys are nodes and values are lists of adjacent nodes.

    Returns:
    bool: True if the graph is a tree, False otherwise.
    """
    visited = set()

    def dfs(node, parent=None):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor != parent and not dfs(neighbor, node):
                return False
        return True

    if not graph:
        return True

    start_node = next(iter(graph))
    if not dfs(start_node):
        return False

    return len(visited) == len(graph)
