from collections import deque

class TextEditor:
    def __init__(self):
        self.buffer = deque()
        self.history = deque()

    def _push_operation(self, operation, params):
        """Pushes the operation and its parameters to the history."""
        self.history.append((operation, params))

    def insert(self, string):
        """Inserts a string at the end of the buffer."""
        self.buffer.extend(string)
        self._push_operation('insert', string)

    def delete(self, num):
        """Deletes the last 'num' characters from the buffer."""
        to_delete = list(self.buffer)[-num:]
        for _ in range(min(num, len(self.buffer))):
            self.buffer.pop()
        self._push_operation('delete', to_delete)

    def print_(self, index):
        """Prints the character at the specified index."""
        if 0 <= index < len(self.buffer):
            print(self.buffer[index])
        else:
            print("Index out of bounds")

    def undo(self):
        """Undoes the last operation."""
        if not self.history:
            return
        operation, params = self.history.pop()
        if operation == 'insert':
            self.delete(len(params))
        elif operation == 'delete':
            self.insert(params)

def main():
    editor = TextEditor()
    operations = [
        ('insert', 'hello'),
        ('insert', 'world'),
        ('delete', 1),
        ('print', 5),
        ('undo', None),
        ('print', 6),
        ('undo', None),
        ('print', 4)
    ]

    for op, param in operations:
        if op == 'insert':
            editor.insert(param)
        elif op == 'delete':
            editor.delete(param)
        elif op == 'print':
            editor.print_(param)
        elif op == 'undo':
            editor.undo()

if __name__ == '__main__':
    main()
