class MinStack:
    def __init__(self):
        # Main stack to store all the elements
        self.stack = []
        # Auxiliary stack to store the minimum elements
        self.min_stack = []

    def push(self, x: int) -> None:
        """Pushes element x onto the stack."""
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self) -> None:
        """Removes the element on top of the stack."""
        if self.stack and self.stack[-1] == self.min_stack[-1]:
            self.min_stack.pop()
        self.stack.pop()

    def top(self) -> int:
        """Returns the top element of the stack."""
        if self.stack:
            return self.stack[-1]

    def get_min(self) -> int:
        """Returns the minimum element in the stack."""
        if self.min_stack:
            return self.min_stack[-1]
