        Adds a new node with the specified data to the end of the list.
        :param data: The data to be stored in the new node.
        """
        new_node = Node(data)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def remove_node(self, key):
        """
        Removes the first node with the specified key from the list.
        :param key: The data of the node to be removed.
        """
        current = self.head
        prev = None
        while current and current.data != key:
            prev = current
            current = current.next

        if not current:
            return

        if not prev:
            self.head = current.next
        else:
            prev.next = current.next

    def print_list(self):
        """
        Prints the elements of the list in order, separated by " -> ", and ending with "None".
        """
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")
