class ShoppingCart:
    def __init__(self):
        """Initialize an empty dictionary to store cart items (item_name: [quantity, price_per_item])."""
        self.items = {}

    def add_item(self, item_name, quantity, price_per_item):
        """Add a specified quantity of an item to the cart at a given price per item.
        If the item already exists, update its quantity and price."""
        if item_name in self.items:
            self.items[item_name][0] += quantity
            self.items[item_name][1] = price_per_item
        else:
            self.items[item_name] = [quantity, price_per_item]

    def remove_item(self, item_name, quantity=None):
        """Remove a specified quantity of an item from the cart.
        If no quantity is specified or the quantity is greater than or equal to the current quantity, remove the item entirely."""
        if quantity is None or quantity >= self.items[item_name][0]:
            del self.items[item_name]
        else:
            self.items[item_name][0] -= quantity

    def list_items(self):
        """Return a list of items in the cart along with their quantity, price per item, and total price."""
        return [(item, details[0], details[1], details[0] * details[1]) for item, details in self.items.items()]

    def calculate_total(self):
        """Calculate the total price of the items in the cart."""
        return sum(details[0] * details[1] for details in self.items.values())
