class Library:
    def __init__(self):
        """Initialize the library with a dictionary to store book titles and their available counts."""
        self.books = {}

    def add_book(self, title, count=1):
        """Add books to the library. If the book already exists, increase the count."""
        if title in self.books:
            self.books[title] += count
        else:
            self.books[title] = count

    def borrow_book(self, title):
        """Borrow a book from the library if available. Return True if successful, otherwise False."""
        if title in self.books and self.books[title] > 0:
            self.books[title] -= 1
            return True
        else:
            return False

    def return_book(self, title):
        """Return a book to the library. If the book does not exist, add it with a count of 1."""
        if title in self.books:
            self.books[title] += 1
        else:
            self.books[title] = 1

    def list_available_books(self):
        """List all books available in the library along with the number of copies."""
        return {title: count for title, count in self.books.items() if count > 0}
