def maximumSwap(num: int) -> int:
    """
    Given a non-negative integer, returns the maximum valued number
    that can be obtained by swapping two digits at most once.

    :param num: Integer to be processed
    :return: Maximum valued integer after at most one swap
    """
    digits = list(str(num))
    n = len(digits)
    last = {d: i for i, d in enumerate(digits)}

    for i in range(n):
        for d in range(9, int(digits[i]), -1):
            d = str(d)
            if last.get(d, -1) > i:
                digits[i], digits[last[d]] = digits[last[d]], digits[i]
                return int("".join(digits))

    return num
