def evaluate_expression(expression):
    """
    Evaluates a mathematical expression provided as a string.

    :param expression: A string representing the mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix.split():
            if token.isdigit():
                stack.append(int(token))
            else:
                val2 = stack.pop()
                val1 = stack.pop()
                if token == '+':
                    result = val1 + val2
                elif token == '-':
                    result = val1 - val2
                elif token == '*':
                    result = val1 * val2
                elif token == '/':
                    result = val1 / val2
                stack.append(result)
        return stack.pop()

    def infix_to_postfix(expression):
        operators = []
        postfix = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = 0
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                postfix.append(str(num))
                continue
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expression[i])):
                postfix.append(operators.pop())
            operators.append(expression[i])
            i += 1

        while operators:
            postfix.append(operators.pop())

        return ' '.join(postfix)

    postfix_expression = infix_to_postfix(expression)
    return evaluate_postfix(postfix_expression)

