def get_unique_values(nested_dict):
    """
    Extracts all unique values from a nested dictionary.

    :param nested_dict: A dictionary that may contain nested dictionaries and lists.
    :return: A list of unique values found in the dictionary.
    """
    seen_values = set()

    def search_values(dictionary):
        for key, value in dictionary.items():
            if isinstance(value, dict):
                search_values(value)
            elif isinstance(value, list):
                for item in value:
                    seen_values.add(item)
            else:
                seen_values.add(value)

    search_values(nested_dict)
    return list(seen_values)
