def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers less than n.

    :param n: An integer representing the upper limit.
    :return: The sum of all prime numbers less than n.
    """
    if n < 2:
        return 0  # No prime numbers less than 2

    primes = [2]
    for num in range(3, n, 2):  # Check only odd numbers starting from 3
        is_prime = True
        for p in primes:
            if p * p > num:
                break  # No need to check further if p squared is greater than num
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return sum(primes)
