def min_jumps(arr):
    """
    Calculate the minimum number of jumps required to reach the end of the array.

    :param arr: List[int] - An array of non-negative integers where each element represents the maximum number of steps that can be made forward from that position.
    :return: int - The minimum number of jumps required to reach the last index of the array. Returns float('inf') if it is not possible to reach the end.
    """
    if len(arr) <= 1:
        return 0
    if arr[0] == 0:
        return float('inf')

    jumps = [float('inf')] * len(arr)
    jumps[0] = 0

    for i in range(1, len(arr)):
        for j in range(i):
            if i <= j + arr[j] and jumps[j] != float('inf'):
                jumps[i] = min(jumps[i], jumps[j] + 1)
                break

    return jumps[-1]

