def longest_palindrome(s: str) -> str:
    """
    Finds the longest palindromic subsequence in the given string s.
    If multiple such palindromes exist, returns the one that appears first lexicographically.

    :param s: Input string
    :return: Longest palindromic subsequence
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    i, j = 0, n - 1
    result = []
    while i <= j:
        if s[i] == s[j]:
            result.append(s[i])
            i += 1
            j -= 1
        elif dp[i + 1][j] > dp[i][j - 1]:
            i += 1
        else:
            j -= 1

    if dp[0][n - 1] % 2 == 0:
        return ''.join(result) + ''.join(result[::-1])
    else:
        return ''.join(result) + ''.join(result[:-1][::-1])
