def evaluate_postfix(expression: str) -> int:
    """
    Evaluates a given postfix expression and returns the result.

    :param expression: A string representing a valid postfix expression.
    :return: The integer result of the postfix expression evaluation.
    """
    stack = []

    for char in expression:
        if char.isdigit():
            stack.append(int(char))
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()

            if char == '+':
                stack.append(operand1 + operand2)
            elif char == '-':
                stack.append(operand1 - operand2)
            elif char == '*':
                stack.append(operand1 * operand2)
            elif char == '/':
                stack.append(operand1 // operand2)

    return stack.pop()
