class Polynomial:
    def __init__(self, terms=None):
        """
        Initializes the polynomial with given terms.
        :param terms: A dictionary where keys are exponents and values are coefficients.
        """
        if terms is None:
            self.terms = {}
        else:
            self.terms = terms

    def __add__(self, other):
        """
        Adds two polynomials.
        :param other: Another Polynomial object.
        :return: A new Polynomial object representing the sum.
        """
        result = Polynomial()
        result.terms = self.terms.copy()
        for exp, coeff in other.terms.items():
            if exp in result.terms:
                result.terms[exp] += coeff
            else:
                result.terms[exp] = coeff
        return result

    def __sub__(self, other):
        """
        Subtracts the second polynomial from the first.
        :param other: Another Polynomial object.
        :return: A new Polynomial object representing the difference.
        """
        result = Polynomial()
        result.terms = self.terms.copy()
        for exp, coeff in other.terms.items():
            if exp in result.terms:
                result.terms[exp] -= coeff
            else:
                result.terms[exp] = -coeff
        return result

    def __mul__(self, other):
        """
        Multiplies two polynomials.
        :param other: Another Polynomial object.
        :return: A new Polynomial object representing the product.
        """
        result = Polynomial()
        for exp1, coeff1 in self.terms.items():
            for exp2, coeff2 in other.terms.items():
                exp = exp1 + exp2
                if exp in result.terms:
                    result.terms[exp] += coeff1 * coeff2
                else:
                    result.terms[exp] = coeff1 * coeff2
        return result

    def __str__(self):
        """
        Returns a string representation of the polynomial.
        :return: A string representing the polynomial.
        """
        terms = sorted(self.terms.items(), reverse=True)
        return " + ".join(f"{coeff}x^{exp}" for exp, coeff in terms if coeff != 0) or "0"
