import unittest

def calculate_median(numbers):
    """
    Calculate the median of a list of numbers.

    :param numbers: List of numbers (integers or floats)
    :return: Median value (float)
    :raises ValueError: If the list is empty
    """
    if not numbers:
        raise ValueError("The list is empty")

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    mid = n // 2

    if n % 2 == 1:
        return sorted_numbers[mid]
    else:
        return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2

class TestCalculateMedian(unittest.TestCase):
    def test_odd_length_list(self):
        self.assertEqual(calculate_median([1, 3, 5, 7, 9]), 5)

    def test_even_length_list(self):
        self.assertEqual(calculate_median([2, 4, 6, 8, 10, 12]), 7)

    def test_single_element_list(self):
        self.assertEqual(calculate_median([42]), 42)

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            calculate_median([])

    def test_negative_numbers(self):
        self.assertEqual(calculate_median([-5, -3, -1, -7, -9]), -5)

    def test_mixed_numbers(self):
        self.assertEqual(calculate_median([-1, 0, 1]), 0)

    def test_float_numbers(self):
        self.assertEqual(calculate_median([1.5, 2.5, 3.5, 4.5, 5.5]), 3.5)

