def inorder_traversal(root):
    """
    Perform an in-order traversal of a binary search tree.

    :param root: TreeNode, the root of the binary search tree.
    :return: List[int], the in-order traversal of the tree.
    """
    def traverse(node):
        if not node:
            return []
        return traverse(node.left) + [node.value] + traverse(node.right)

    return traverse(root)
