    Finds the length of the longest subsequence in the given list of integers
    where each element is divisible by the preceding element.

    :param numbers: List of integers
    :return: Length of the longest evenly divisible subsequence
    """
    if not numbers:
        return 0

    lds = [1] * len(numbers)

    for i in range(1, len(numbers)):
        for j in range(i):
            if numbers[i] % numbers[j] == 0 and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    return max(lds)

