def three_sum(nums):
    """
    Finds the number of unique triplets in the list that sum up to zero.

    :param nums: List of integers
    :return: Integer, the number of unique triplets that sum up to zero
    """
    nums.sort()
    triplets = set()

    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, len(nums) - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                triplets.add((nums[i], nums[left], nums[right]))
                left += 1
                right -= 1

                while left < right and nums[left] == nums[left - 1]:
                    left += 1
                while left < right and nums[right] == nums[right + 1]:
                    right -= 1

            elif total < 0:
                left += 1
            else:
                right -= 1

    return len(triplets)

# Example usage:
