def can_be_strictly_increasing(sequence):
    """
    Determines if a sequence can be made strictly increasing by removing at most one element.

    :param sequence: List[int] - The input sequence of integers.
    :return: bool - True if the sequence can be made strictly increasing by removing at most one element, False otherwise.
    """
    def is_strictly_increasing(subseq):
        """
        Checks if a given subsequence is strictly increasing.

        :param subseq: List[int] - The subsequence to check.
        :return: bool - True if the subsequence is strictly increasing, False otherwise.
        """
        return all(subseq[i] < subseq[i+1] for i in range(len(subseq) - 1))

    for i in range(len(sequence) - 1):
        if sequence[i] >= sequence[i+1]:
            return is_strictly_increasing(sequence[:i] + sequence[i+1:]) or is_strictly_increasing(sequence[:i+1] + sequence[i+2:])
    return True
