def splitArray(nums, k):
    """
    Partitions the array into k non-empty contiguous subarrays such that the maximum sum among these subarrays is minimized.

    :param nums: List[int] - The array of integers to be partitioned.
    :param k: int - The number of partitions.
    :return: int - The minimized maximum sum of the partitions.
    """
    def can_split(max_sum):
        current_sum = 0
        count = 1
        for num in nums:
            if current_sum + num > max_sum:
                count += 1
                current_sum = num
                if count > k:
                    return False
            else:
                current_sum += num
        return True

    left = max(nums)
    right = sum(nums)

    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1

    return left
