class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Stack:
    def __init__(self):
        self.top = None
        self.count = 0

    def push(self, item):
        """Adds an item to the top of the stack."""
        new_node = Node(item)
        new_node.next = self.top
        self.top = new_node
        self.count += 1

    def pop(self):
        """Removes and returns the item from the top of the stack. Raises IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("pop from empty stack")
        popped_item = self.top.data
        self.top = self.top.next
        self.count -= 1
        return popped_item

    def peek(self):
        """Returns the item at the top of the stack without removing it. Raises IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self.top.data

    def is_empty(self):
        """Returns True if the stack is empty, otherwise False."""
        return self.top is None

    def size(self):
        """Returns the number of items in the stack."""
        return self.count
