def is_acyclic(graph):
    """
    Determines if a directed graph is acyclic using Depth-First Search (DFS).

    :param graph: A dictionary representing the graph, where keys are vertices and values are lists of adjacent vertices.
    :return: True if the graph is acyclic, False otherwise.
    """
    visited = set()
    recursion_stack = set()

    def dfs(vertex):
        visited.add(vertex)
        recursion_stack.add(vertex)

        for neighbor in graph[vertex]:
            if neighbor not in visited:
                if not dfs(neighbor):
                    return False
            elif neighbor in recursion_stack:
                return False

        recursion_stack.remove(vertex)
        return True

    for node in graph:
        if node not in visited:
            if not dfs(node):
                return False
    return True

