    Finds the longest increasing subsequence of consecutive elements in a list of integers.

    :param nums: List of integers
    :return: List of integers representing the longest increasing subsequence
    """
    if not nums:
        return []

    max_seq = current_seq = [nums[0]]

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_seq.append(nums[i])
        else:
            if len(current_seq) > len(max_seq):
                max_seq = current_seq
            current_seq = [nums[i]]

    if len(current_seq) > len(max_seq):
        max_seq = current_seq

