class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.key = key

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """
        Inserts a new key into the BST.

        :param key: The key to be inserted.
        """
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """
        Helper method to insert a new key into the BST.

        :param node: The current node in the BST.
        :param key: The key to be inserted.
        """
        if key < node.key:
            if node.left is None:
                node.left = Node(key)  # Create a new Node and attach it to the left
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = Node(key)  # Create a new Node and attach it to the right
            else:
                self._insert(node.right, key)

    def inorder_traversal(self, node):
        """
        Returns the in-order traversal of the BST starting from the given node.

        :param node: The starting node for the traversal.
        :return: A list of integers representing the in-order traversal.
        """
        res = []
        if node is not None:
            res = self.inorder_traversal(node.left)
            res.append(node.key)
            res = res + self.inorder_traversal(node.right)
        return res

