def longest_zigzag_subsequence(sequence):
    """
    Calculate the length of the longest zigzag subsequence in a given sequence of integers.

    :param sequence: List of integers representing the sequence.
    :return: Integer, the length of the longest zigzag subsequence.
    """
    if len(sequence) < 2:
        return len(sequence)

    up = [1] * len(sequence)
    down = [1] * len(sequence)

    for i in range(1, len(sequence)):
        if sequence[i] > sequence[i - 1]:
            up[i] = down[i - 1] + 1
        elif sequence[i] < sequence[i - 1]:
            down[i] = up[i - 1] + 1

    return max(max(up), max(down))

