def longest_alternating_subsequence(nums):
    """
    Finds the length of the longest alternating subsequence in the given array.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest alternating subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    inc = [1] * n  # length of the longest alternating subsequence ending at index i with an increasing element
    dec = [1] * n  # length of the longest alternating subsequence ending at index i with a decreasing element

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            inc[i] = dec[i - 1] + 1
        elif nums[i] < nums[i - 1]:
            dec[i] = inc[i - 1] + 1

    return max(max(inc), max(dec))
