def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def list_primes_in_range(start, end):
    """List all prime numbers within a given range [start, end]."""
    return [num for num in range(start, end + 1) if is_prime(num)]

