def compare_string_frequencies(str1, str2):
    """
    Returns a dictionary with characters from str1 as keys and tuples as values.
    Each tuple contains the frequency of the character in str1, the frequency in str2,
    and the difference between these frequencies.

    :param str1: First input string
    :param str2: Second input string
    :return: Dictionary with character frequencies and differences
    """
    freq_dict = {}

    for char in str1:
        if char in freq_dict:
            freq_dict[char][0] += 1
        else:
            freq_dict[char] = [1, 0, 0]

    for char in str2:
        if char in freq_dict:
            freq_dict[char][1] += 1
        else:
            freq_dict[char] = [0, 1, 0]

    for char in freq_dict:
        freq_dict[char][2] = freq_dict[char][0] - freq_dict[char][1]

    return {char: freq_dict[char] for char in str1 if char in freq_dict}

