from math import gcd

class Fraction:
    def __init__(self, numerator=0, denominator=1):
        """
        Initialize a Fraction object with a given numerator and denominator.
        Simplify the fraction and ensure the denominator is positive.
        """
        if denominator == 0:
            raise ValueError("Denominator cannot be zero.")
        common_divisor = gcd(numerator, denominator)
        self.numerator = numerator // common_divisor
        self.denominator = denominator // common_divisor
        if self.denominator < 0:
            self.numerator = -self.numerator
            self.denominator = -self.denominator

    def __add__(self, other):
        """
        Add two Fraction objects and return the result as a new Fraction.
        """
        if isinstance(other, Fraction):
            new_numerator = self.numerator * other.denominator + other.numerator * self.denominator
            new_denominator = self.denominator * other.denominator
            return Fraction(new_numerator, new_denominator)
        else:
            raise TypeError(f"Unsupported operand type for +: 'Fraction' and '{type(other).__name__}'")

    def __sub__(self, other):
        """
        Subtract one Fraction object from another and return the result as a new Fraction.
        """
        if isinstance(other, Fraction):
            new_numerator = self.numerator * other.denominator - other.numerator * self.denominator
            new_denominator = self.denominator * other.denominator
            return Fraction(new_numerator, new_denominator)
        else:
            raise TypeError(f"Unsupported operand type for -: 'Fraction' and '{type(other).__name__}'")

    def __mul__(self, other):
        """
        Multiply two Fraction objects and return the result as a new Fraction.
        """
        if isinstance(other, Fraction):
            new_numerator = self.numerator * other.numerator
            new_denominator = self.denominator * other.denominator
            return Fraction(new_numerator, new_denominator)
        else:
            raise TypeError(f"Unsupported operand type for *: 'Fraction' and '{type(other).__name__}'")

    def __truediv__(self, other):
        """
        Divide one Fraction object by another and return the result as a new Fraction.
        """
        if isinstance(other, Fraction):
            if other.numerator == 0:
                raise ZeroDivisionError("Cannot divide by zero.")
            new_numerator = self.numerator * other.denominator
            new_denominator = self.denominator * other.numerator
            return Fraction(new_numerator, new_denominator)
        else:
            raise TypeError(f"Unsupported operand type for /: 'Fraction' and '{type(other).__name__}'")

    def __str__(self):
        """
        Return the string representation of the Fraction in the form "numerator/denominator".
        """
        return f"{self.numerator}/{self.denominator}"

    def __eq__(self, other):
        """
        Check if two Fraction objects are equal.
        """
        return (self.numerator == other.numerator and self.denominator == other.denominator) if isinstance(other, Fraction) else False
