def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def findMinPrimeDiff(numbers):
    """Find the minimum difference between any two prime numbers in the list."""
    primes = [num for num in numbers if is_prime(num)]
    primes.sort()

    if len(primes) < 2:
        return -1

    min_diff = float('inf')
    for i in range(len(primes) - 1):
        min_diff = min(min_diff, primes[i + 1] - primes[i])

    return min_diff

