def matrix_multiply(mat1, mat2):
    """Multiplies two 2x2 matrices and returns the result."""
    a, b, c, d = mat1[0][0], mat1[0][1], mat1[1][0], mat1[1][1]
    e, f, g, h = mat2[0][0], mat2[0][1], mat2[1][0], mat2[1][1]
    return [[a*e + b*g, a*f + b*h], [c*e + d*g, c*f + d*h]]

def matrix_power(matrix, n):
    """Computes the power of a matrix using exponentiation by squaring."""
    if n == 0:
        return [[1, 0], [0, 1]]  # Identity matrix
    if n == 1:
        return matrix
    half_power = matrix_power(matrix, n // 2)
    if n % 2 == 0:
        return matrix_multiply(half_power, half_power)
    else:
        return matrix_multiply(matrix_multiply(half_power, half_power), matrix)

def fibonacci(n):
    """Computes the nth Fibonacci number using matrix exponentiation."""
    if n == 0:
        return 0
    if n == 1:
        return 1
    F = [[1, 1], [1, 0]]
    result = matrix_power(F, n - 1)
    return result[0][0]

