import json

def extract_urls_from_json(data, urls=None):
    """
    Recursively extracts URLs from a nested JSON structure.

    :param data: The JSON data to search through.
    :param urls: A list to accumulate URLs found in the JSON data.
    :return: A list of URLs found in the JSON data.
    """
    if urls is None:
        urls = []

    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, str) and value.startswith(('http://', 'https://')):
                urls.append(value)
            else:
                extract_urls_from_json(value, urls)
    elif isinstance(data, list):
        for item in data:
            extract_urls_from_json(item, urls)

    return urls

