    Parses a JSON file and extracts all URLs from it.

    :param file_path: The path to the JSON file.
    :return: A list of URLs found in the JSON file.
    """
    with open(file_path, 'r') as file:
        data = json.load(file)

    return extract_urls_from_json(data)
