class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new key into the binary search tree."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def search(self, key):
        """Returns True if the key is present in the tree, otherwise False."""
        return self._search(self.root, key)

    def _search(self, node, key):
        if node is None or node.val == key:
            return node is not None
        if key < node.val:
            return self._search(node.left, key)
        return self._search(node.right, key)

    def delete(self, key):
        """Deletes a key from the binary search tree."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return node
        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            temp = self._min_value_node(node.right)
            node.val = temp.val
            node.right = self._delete(node.right, temp.val)
        return node

    def min_value(self):
        """Returns the minimum value in the tree."""
        if self.root is None:
            return None
        current = self.root
        return self._min_value_node(current).val

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def max_value(self):
        """Returns the maximum value in the tree."""
        if self.root is None:
            return None
        current = self.root
        return self._max_value_node(current).val

    def _max_value_node(self, node):
        current = node
        while current.right is not None:
            current = current.right
        return current

# Demonstrating the functionality of the class
