import random

def is_valid(board, row, col, num):
    """
    Check if placing num in board[row][col] is valid according to Sudoku rules.
    """
    for x in range(9):
        if board[row][x] == num or board[x][col] == num:
            return False

    start_row = row - row % 3
    start_col = col - col % 3
    for i in range(3):
        for j in range(3):
            if board[i + start_row][j + start_col] == num:
                return False

    return True

def solve_sudoku(board):
    """
    Solve the Sudoku puzzle using backtracking.
    """
    empty = find_empty_location(board)
    if not empty:
        return True
    row, col = empty

    for num in range(1, 10):
        if is_valid(board, row, col, num):
            board[row][col] = num
            if solve_sudoku(board):
                return True
            board[row][col] = 0

    return False

def find_empty_location(board):
    """
    Find an empty location (represented by 0) in the board.
    """
    for i in range(9):
        for j in range(9):
            if board[i][j] == 0:
                return (i, j)
    return None

def fill_board(board):
    """
    Fill the board with numbers to create a complete Sudoku solution.
    """
    numbers = list(range(1, 10))
    for i in range(81):
        row = i // 9
        col = i % 9
        if board[row][col] == 0:
            random.shuffle(numbers)
            for num in numbers:
                if is_valid(board, row, col, num):
                    board[row][col] = num
                    if fill_board(board):
                        return True
                    board[row][col] = 0
            return False
    return True

def remove_numbers_from_board(board, n):
    """
    Remove n numbers from the board to create a Sudoku puzzle.
    """
    empty = n  # Total number of cells to set to 0
    while empty > 0:
        i = random.randint(0, 8)
        j = random.randint(0, 8)
        if board[i][j] != 0:
            board[i][j] = 0
            empty -= 1

def generate_sudoku():
    """
    Generate a 9x9 Sudoku puzzle with a unique solution.
    """
    board = [[0 for i in range(9)] for j in range(9)]
    fill_board(board)
    remove_numbers_from_board(board, 50)  # Remove 50 numbers to create a puzzle
    return board

def print_board(board):
    """
    Print the Sudoku board.
    """
    for row in board:
        print(" ".join(str(num) if num != 0 else '.' for num in row))

# Generate and print a Sudoku puzzle
