                print(f"{task_id}: {details['description']} [{details['status']}]")

    def mark_completed(self, task_id):
        """
        Marks the task with the specified ID as completed.
        """
        if task_id in self.tasks:
            if self.tasks[task_id]['status'] == 'completed':
