def count_palindrome_pairs(words):
    """
    Counts the number of unique pairs of strings from the list that form a palindrome when concatenated.

    :param words: List of strings
    :return: Integer count of unique palindrome pairs
    """
    def is_palindrome(s):
        return s == s[::-1]

    word_dict = {word: i for i, word in enumerate(words)}
    palindrome_pairs = set()

    for i, word in enumerate(words):
        for j in range(len(word) + 1):
            left, right = word[:j], word[j:]

            if is_palindrome(right) and left[::-1] in word_dict and word_dict[left[::-1]] != i:
                palindrome_pairs.add((i, word_dict[left[::-1]]))

            if j != len(word) and is_palindrome(left) and right[::-1] in word_dict and word_dict[right[::-1]] != i:
                palindrome_pairs.add((word_dict[right[::-1]], i))

    return len(palindrome_pairs)
