def four_sum(nums, target):
    """
    Finds all unique quadruplets in the list that sum up to the target.

    :param nums: List of integers.
    :param target: Target sum for the quadruplets.
    :return: List of unique quadruplets.
    """
    nums.sort()
    quadruplets = set()

    def find_quadruplets(i, j, target):
        left, right = j + 1, len(nums) - 1
        while left < right:
            total = nums[i] + nums[j] + nums[left] + nums[right]
            if total == target:
                quadruplets.add((nums[i], nums[j], nums[left], nums[right]))
                left += 1
                right -= 1
            elif total < target:
                left += 1
            else:
                right -= 1

    for i in range(len(nums) - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, len(nums) - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            find_quadruplets(i, j, target)

    return list(quadruplets)

def main():
    """
    Reads input, computes the unique quadruplets, and prints them.
    """
    n = int(input())
    nums = list(map(int, input().split()))
    target = int(input())
    result = four_sum(nums, target)
    for quad in sorted(result):
        print(' '.join(map(str, quad)))

if __name__ == "__main__":
    main()
