def most_frequent_second_item(tuples_list):
    """
    Determine the most frequent second item in a list of tuples.
    If there are ties, return the largest integer.

    :param tuples_list: List of tuples, where each tuple contains a character and an integer.
    :return: Integer representing the most frequent second item.
    """
    frequency_dict = {}
    value_dict = {}

    for _, value in tuples_list:
        if value in frequency_dict:
            frequency_dict[value] += 1
        else:
            frequency_dict[value] = 1

        if frequency_dict[value] not in value_dict or value_dict[frequency_dict[value]] < value:
            value_dict[frequency_dict[value]] = value

    max_frequency = max(frequency_dict.values())
    return value_dict[max_frequency]
