import json

def find_value_in_nested_json(filename, key):
    """
    Reads a JSON file and returns the value associated with a specified key.
    Handles nested JSON objects and arrays.

    :param filename: str, the name of the JSON file to read.
    :param key: str, the key whose value needs to be found.
    :return: The value associated with the key, or None if the key does not exist.
    """
    def search(d, target_key):
        if isinstance(d, dict):
            for k, v in d.items():
                if k == target_key:
                    return v
                elif isinstance(v, (dict, list)):
                    result = search(v, target_key)
                    if result is not None:
                        return result
        elif isinstance(d, list):
            for item in d:
                result = search(item, target_key)
                if result is not None:
                    return result
        return None

    with open(filename, 'r') as file:
        data = json.load(file)
        return search(data, key)
