        if not self.products:
            print("No products in the store.")
            return
        for name, details in self.products.items():
            print(f"Product: {name}, Price: ${details['price']:.2f}, Quantity: {details['quantity']}")

    def purchase_product(self, name, quantity):
        """Purchases a specified quantity of a product, handling out-of-stock and over-request scenarios."""
