def evaluate_postfix(expression):
    """
    Evaluates a postfix expression given as a list of strings.

    :param expression: List of strings representing the postfix expression.
    :return: Integer result of the postfix expression.
    """
    stack = []

    for token in expression:
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            stack.append(int(token))
        else:
            a = stack.pop()
            b = stack.pop()
            if token == '+':
                stack.append(b + a)
            elif token == '-':
                stack.append(b - a)
            elif token == '*':
                stack.append(b * a)
            elif token == '/':
                stack.append(int(b / a))

    return stack.pop()

# Example usage:
expression = ['2', '3', '4', '+', '*']
print(evaluate_postfix(expression))  # Output: 14
