def evaluate_postfix(expression: str) -> int:
    """
    Evaluates a postfix expression consisting of integers and operators (+, -, *, /).

    :param expression: A string representing the postfix expression.
    :return: An integer representing the result of the postfix expression evaluation.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    tokens = expression.split()

    for token in tokens:
        if token not in operators:
            stack.append(int(token))
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()

            if token == '+':
                result = operand1 + operand2
            elif token == '-':
                result = operand1 - operand2
            elif token == '*':
                result = operand1 * operand2
            elif token == '/':
                result = operand1 // operand2

            stack.append(result)

    return stack.pop()
