class MinStack:
    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, x):
        """Push element x onto stack."""
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        """Remove the element on top of the stack and return it. Raise IndexError if stack is empty."""
        if self.stack:
            if self.stack[-1] == self.min_stack[-1]:
                self.min_stack.pop()
            return self.stack.pop()
        raise IndexError("pop from empty stack")

    def peek(self):
        """Return the top element of the stack. Raise IndexError if stack is empty."""
        if self.stack:
            return self.stack[-1]
        raise IndexError("peek from empty stack")

    def get_min(self):
        """Return the minimum element in the stack. Raise IndexError if stack is empty."""
        if self.min_stack:
            return self.min_stack[-1]
        raise IndexError("get_min from empty stack")

