def are_parentheses_balanced(s: str) -> bool:
    """
    Determines if the parentheses in the string are balanced.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the parentheses are balanced, otherwise False.
    """
    stack = []
    opening_parentheses = {'(', '{', '['}
    closing_parentheses = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in opening_parentheses:
            stack.append(char)
        elif char in closing_parentheses:
            if not stack or stack[-1] != closing_parentheses[char]:
                return False
            stack.pop()

    return not stack
