import numpy as np
import sys

def generate_random_numbers(distribution, params, size=1000):
    """
    Generates random numbers according to a specified probability distribution.

    Parameters:
        distribution (str): The type of distribution ('normal', 'uniform', 'exponential').
        params (dict): A dictionary of parameters specific to the distribution.
                       For 'normal': mean (mu) and standard deviation (sigma).
                       For 'uniform': low and high.
                       For 'exponential': scale (lambda, the inverse rate parameter).
        size (int): The number of random samples to generate.

    Returns:
        np.ndarray: A numpy array of random numbers.
    """
    if distribution == 'normal':
        mu = params.get('mu', 0)
        sigma = params.get('sigma', 1)
        return np.random.normal(mu, sigma, size)
    elif distribution == 'uniform':
        low = params.get('low', 0)
        high = params.get('high', 1)
        if low > high:
            print("Invalid range for uniform distribution (low must be less than high)")
            sys.exit(1)
        return np.random.uniform(low, high, size)
    elif distribution == 'exponential':
        scale = params.get('scale', 1)
        if scale <= 0:
            print("Invalid scale for exponential distribution (must be positive)")
            sys.exit(1)
        return np.random.exponential(scale, size)
    else:
        print(f"Unsupported distribution type: {distribution}")
        sys.exit(1)

# Example usage
