def find_cycles(graph):
    """
    Finds all distinct cycles in a directed graph represented as an adjacency list.

    :param graph: A dictionary where keys are node identifiers and values are lists of adjacent nodes.
    :return: A list of lists, where each inner list represents a distinct cycle in the graph.
    """
    def dfs(node, path, visited):
        visited[node] = True
        path.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, path, visited)
            elif neighbor in path:
                cycles.append(path[path.index(neighbor):])

        path.pop()
        visited[node] = False

    cycles = []
    visited = {node: False for node in graph}

    for node in graph:
        if not visited[node]:
            dfs(node, [], visited)

    return cycles
