def find_substring_indices(s, patterns):
    """
    Returns a dictionary with patterns as keys and lists of starting indices in the string `s` where each pattern occurs.

    :param s: The input string.
    :param patterns: A list of substring patterns to search for in the string `s`.
    :return: A dictionary with patterns as keys and lists of starting indices as values.
    """
    result = {pattern: [] for pattern in patterns}
    for pattern in patterns:
        start = 0
        while start <= len(s) - len(pattern):
            pos = s.find(pattern, start)
            if pos != -1:
                result[pattern].append(pos)
                start = pos + 1
            else:
                break
    return result
