def evaluate_postfix(expression: str) -> int:
    """
    Evaluates a given postfix expression and returns the result.

    :param expression: A string representing a postfix expression.
    :return: The result of the postfix expression evaluation.
    """
    stack = []
    tokens = expression.split()
    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()
            if token == '+':
                result = operand1 + operand2
            elif token == '-':
                result = operand1 - operand2
            elif token == '*':
                result = operand1 * operand2
            elif token == '/':
                result = operand1 / operand2
            stack.append(result)
    return int(stack.pop())

# Example usage:
