class Graph:
    def __init__(self):
        """Initializes an empty graph with an adjacency list."""
        self.adjacency_list = {}

    def add_edge(self, v1, v2):
        """Adds an undirected edge between vertices v1 and v2."""
        if v1 not in self.adjacency_list:
            self.adjacency_list[v1] = []
        if v2 not in self.adjacency_list:
            self.adjacency_list[v2] = []
        self.adjacency_list[v1].append(v2)
        self.adjacency_list[v2].append(v1)

    def remove_edge(self, v1, v2):
        """Removes the undirected edge between vertices v1 and v2."""
        if v1 in self.adjacency_list and v2 in self.adjacency_list[v1]:
            self.adjacency_list[v1].remove(v2)
        if v2 in self.adjacency_list and v1 in self.adjacency_list[v2]:
            self.adjacency_list[v2].remove(v1)

    def dfs(self, v, visited, component):
        """Performs depth-first search and collects vertices in the current connected component."""
        visited.add(v)
        component.append(v)
        for neighbor in self.adjacency_list.get(v, []):
            if neighbor not in visited:
                self.dfs(neighbor, visited, component)

    def connected_components(self):
        """Finds all connected components in the graph."""
        visited = set()
        components = []

        for vertex in self.adjacency_list:
            if vertex not in visited:
                component = []
                self.dfs(vertex, visited, component)
                components.append(component)

        return components
