def common_characters_indices(str1, str2):
    """
    Returns a dictionary with characters that appear in both input strings as keys.
    The values are lists of lists, where the first inner list contains the indices
    of the character in str1, and the second inner list contains the indices of
    the character in str2.

    :param str1: First input string
    :param str2: Second input string
    :return: Dictionary with common characters and their indices
    """
    common_indices = {}

    for index, char in enumerate(str1):
        if char in str2:
            if char not in common_indices:
                common_indices[char] = {'str1': [], 'str2': []}
            common_indices[char]['str1'].append(index)

    for index, char in enumerate(str2):
        if char in common_indices:
            common_indices[char]['str2'].append(index)

    result = {}
    for char in common_indices:
        if common_indices[char]['str1'] and common_indices[char]['str2']:
            result[char] = [common_indices[char]['str1'], common_indices[char]['str2']]

    return result

