        for key, value in obj.items():
            print(f"{indent}{key}: ", end="")
            print_json(value, indent + "  ")
    elif isinstance(obj, list):
        for index, item in enumerate(obj):
            print(f"{indent}[{index}]: ", end="")
            print_json(item, indent + "  ")
    else:
        print(obj)

