class BankAccount:
    def __init__(self, initial_balance=0):
        """
        Initializes a new BankAccount with the given initial balance.
        The initial balance must not be negative.
        """
        self.balance = max(0, initial_balance)

    def deposit(self, amount):
        """
        Adds the specified amount to the account balance.
        Raises ValueError if the amount is not positive.
        """
        if amount > 0:
            self.balance += amount
        else:
            raise ValueError("Deposit amount must be positive")

    def withdraw(self, amount):
        """
        Subtracts the specified amount from the account balance if sufficient funds are available.
        Raises ValueError if the amount is not positive or if there are insufficient funds.
        """
        if amount > 0:
            if self.balance >= amount:
