class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Insert a new node with the given value into the binary tree."""
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert a new node recursively."""
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)

    def in_order_traversal(self):
        """Return a list of values obtained by in-order traversal of the tree."""
        return self._in_order_traversal_recursively(self.root)

    def _in_order_traversal_recursively(self, node):
        """Helper method to perform in-order traversal recursively."""
        traversal = []
        if node is not None:
            traversal = self._in_order_traversal_recursively(node.left)
            traversal.append(node.value)
            traversal = traversal + self._in_order_traversal_recursively(node.right)
        return traversal

    def height(self, node=None):
        """Compute the height of the tree or a subtree rooted at the given node."""
        if node is None:
            node = self.root
        if node is None:
            return 0
        else:
            left_height = self.height(node.left)
            right_height = self.height(node.right)
            return max(left_height, right_height) + 1

    def is_balanced(self):
        """Check if the tree is balanced."""
        return self._is_balanced_recursively(self.root)

    def _is_balanced_recursively(self, node):
        """Helper method to check if the tree is balanced recursively."""
        if node is None:
            return True

        left_height = self.height(node.left)
        right_height = self.height(node.right)

        if abs(left_height - right_height) <= 1 and self._is_balanced_recursively(node.left) and self._is_balanced_recursively(node.right):
            return True
        return False
