    """
    Determines if the input string s containing brackets is valid.

    A string is valid if all opening brackets are closed in the correct order
    and no additional brackets are present.

    :param s: String containing brackets
    :return: True if the string is valid, False otherwise
    """
    matching_pair = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in s:
        if char in matching_pair.values():
            stack.append(char)
        elif char in matching_pair.keys():
