def longestValidParentheses(s: str) -> int:
    """
    Determine the length of the longest valid (well-formed) parentheses substring in the given string.

    :param s: A string consisting of '(' and ')'.
    :return: The length of the longest valid parentheses substring.
    """
    max_len = 0
    left = 0

    for i in range(len(s)):
        if s[i] == '(':
            left += 1
        else:
            left -= 1

        if left < 0:
            left = 0
        else:
            max_len = max(max_len, i - left + 1)

    left = 0
    max_len2 = 0

    for i in reversed(range(len(s))):
        if s[i] == ')':
            left += 1
        else:
            left -= 1

        if left < 0:
            left = 0
        else:
            max_len2 = max(max_len2, left + i - (len(s) - 1))

    return max(max_len, max_len2)

