def can_form_palindrome(s: str) -> bool:
    """
    Determines if there exists a permutation of the string s that forms a palindrome.

    :param s: A string consisting of lowercase English letters.
    :return: True if a palindromic permutation exists, False otherwise.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    return odd_count <= 1
