class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def boundaryOfBinaryTree(root: TreeNode) -> list:
    """
    Returns a list of boundary nodes of a binary tree in anti-clockwise direction.

    :param root: TreeNode, the root of the binary tree
    :return: List[int], the boundary nodes of the binary tree
    """
    if not root:
        return []

    left_boundary, right_boundary, leaves = [], [], []

    def add_left_boundary(node):
        if not node or (not node.left and not node.right):
            return
        left_boundary.append(node.val)
        if node.left:
            add_left_boundary(node.left)
        else:
            add_left_boundary(node.right)

    def add_right_boundary(node):
        if not node or (not node.left and not node.right):
            return
        right_boundary.append(node.val)
        if node.right:
            add_right_boundary(node.right)
        else:
            add_right_boundary(node.left)

    def add_leaves(node):
        if not node:
            return
        if not node.left and not node.right:
            leaves.append(node.val)
        add_leaves(node.left)
        add_leaves(node.right)

    boundary = [root.val]
    add_left_boundary(root.left)
    add_leaves(root.left)
    add_leaves(root.right)
    add_right_boundary(root.right)
    boundary.extend(left_boundary + leaves + right_boundary[::-1])

    return list(dict.fromkeys(boundary))
