import json

def get_nested_keys(json_str):
    """
    Returns a list of all nested keys in the JSON object represented by the input string.

    :param json_str: A string representing a JSON object.
    :return: A list of strings, where each string is a nested key in the JSON object.
    """
    def extract_keys(obj, parent_key=""):
        keys = []
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_key = f"{parent_key}.{key}" if parent_key else key
                keys.append(new_key)
                keys.extend(extract_keys(value, new_key))
        elif isinstance(obj, list):
            for index, item in enumerate(obj):
                new_key = f"{parent_key}[{index}]"
                keys.extend(extract_keys(item, new_key))
        return keys

    json_obj = json.loads(json_str)
    return extract_keys(json_obj)
