    :param strings: List of strings, where each string may contain multiple words separated by spaces.
    :return: Dictionary with words as keys and their counts as values.
    """
    word_count = {}
    for string in strings:
        words = string.lower().split()
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1
    return word_count

