def findMaxLength(arr):
    """
    Finds the length of the longest contiguous subarray with an equal number of 0s and 1s.

    :param arr: List[int] - A list of integers consisting only of 0s and 1s.
    :return: int - The length of the longest subarray with an equal number of 0s and 1s.
    """
    max_len = 0
    count = 0
    count_dict = {}

    for i in range(len(arr)):
        count += 1 if arr[i] == 1 else -1

        if count == 0:
            max_len = i + 1

        if count in count_dict:
            max_len = max(max_len, i - count_dict[count])
        else:
            count_dict[count] = i

    return max_len
