def find_max_value(json_obj):
    """
    Recursively traverses a dictionary and any nested dictionaries or lists to find
    the maximum numeric value present in the JSON object.

    :param json_obj: dict or list, the JSON object to search for the maximum value
    :return: float or int, the maximum numeric value found in the JSON object
    """
    max_value = float('-inf')  # Initialize with the smallest possible number

    def _rec_max_value(obj):
        nonlocal max_value
        if isinstance(obj, dict):
            for value in obj.values():
                _rec_max_value(value)
        elif isinstance(obj, list):
            for item in obj:
                _rec_max_value(item)
        elif isinstance(obj, (float, int)) and obj > max_value:
            max_value = obj

    _rec_max_value(json_obj)
    return max_value

