```python
def matrix_mult(A, B, mod=None):
    """
    Multiplies two 2x2 matrices A and B.
    If mod is provided, applies modulus to the result.
    """
    a, b, c, d = A
    e, f, g, h = B
    return (
        (a * e + b * g) % mod if mod else (a * e + b * g),
        (a * f + b * h) % mod if mod else (a * f + b * h),
        (c * e + d * g) % mod if mod else (c * e + d * g),
        (c * f + d * h) % mod if mod else (c * f + d * h),
    )

def matrix_power(matrix, power, mod=None):
    """
    Raises a 2x2 matrix to the given power using exponentiation by squaring.
    If mod is provided, applies modulus to the result.
    """
    if power == 0:
        return (1, 0, 0, 1)  # Identity matrix
    elif power == 1:
        return matrix
    elif power % 2 == 0:
        half_power = matrix_power(matrix, power // 2, mod=mod)
        return matrix_mult(half_power, half_power, mod=mod)
    else:
        half_power = matrix_power(matrix, (power - 1) // 2, mod=mod)
        return matrix_mult(matrix_mult(half_power, half_power, mod=mod), matrix, mod=mod)

def fibonacci(n, mod=None):
    """
    Returns the nth Fibonacci number using matrix exponentiation.
    If mod is provided, returns the result modulo mod.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1
    F = (1, 1, 1, 0)  # Transformation matrix
    result = matrix_power(F, n-1, mod=mod)
    return result[0]  # The top left cell contains F(n)
