def is_cyclic_util(graph, node, visited, rec_stack):
    """
    Utility function to detect cycle in the graph using Depth First Search (DFS).

    :param graph: Dictionary representing the adjacency list of the graph.
    :param node: Current node being visited.
    :param visited: Dictionary to keep track of visited nodes.
    :param rec_stack: Dictionary to keep track of nodes in the current recursion stack.
    :return: True if a cycle is detected, False otherwise.
    """
    visited[node] = True
    rec_stack[node] = True

    for neighbor in graph.get(node, []):
        if not visited[neighbor]:
            if is_cyclic_util(graph, neighbor, visited, rec_stack):
                return True
        elif rec_stack[neighbor]:
            return True

    rec_stack[node] = False
    return False

def is_cyclic(graph):
    """
    Determines if the given directed graph contains a cycle.

    :param graph: Dictionary representing the adjacency list of the graph.
    :return: True if the graph contains a cycle, False otherwise.
    """
    visited = {node: False for node in graph}
    rec_stack = {node: False for node in graph}
    for node in graph:
        if not visited[node]:
            if is_cyclic_util(graph, node, visited, rec_stack):
                return True
    return False

