class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key in the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper method to insert a new node with the given key in the BST."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """Delete the node with the given key from the BST."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper method to delete the node with the given key from the BST."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def _min_value_node(self, node):
        """Helper method to find the inorder successor."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def search(self, key):
        """Search for a node with the given key in the BST."""
        return self._search(self.root, key) is not None

    def _search(self, node, key):
        """Helper method to search for a node with the given key in the BST."""
        if node is None or node.val == key:
            return node
        if key > node.val:
            return self._search(node.right, key)
        return self._search(node.left, key)

    def inorder_traversal(self):
        """Return a list of all keys in the BST in ascending order."""
        result = []
        self._inorder_traversal(self.root, result)
        return result

    def _inorder_traversal(self, node, result):
        """Helper method to perform in-order traversal of the BST."""
        if node:
            self._inorder_traversal(node.left, result)
            result.append(node.val)
            self._inorder_traversal(node.right, result)
