class Graph:
    def __init__(self):
        self.vertices = {}

    def add_vertex(self, vertex):
        """Adds a vertex to the graph."""
        if vertex not in self.vertices:
            self.vertices[vertex] = []

    def add_edge(self, vertex1, vertex2):
        """Adds an undirected edge between vertex1 and vertex2."""
        if vertex1 in self.vertices and vertex2 in self.vertices:
            self.vertices[vertex1].append(vertex2)
            self.vertices[vertex2].append(vertex1)

    def remove_vertex(self, vertex):
        """Removes vertex and all edges connected to it."""
        if vertex in self.vertices:
            for connected_vertex in self.vertices[vertex]:
                self.vertices[connected_vertex].remove(vertex)
            del self.vertices[vertex]

    def remove_edge(self, vertex1, vertex2):
        """Removes the undirected edge between vertex1 and vertex2."""
        if vertex1 in self.vertices and vertex2 in self.vertices:
            if vertex2 in self.vertices[vertex1]:
                self.vertices[vertex1].remove(vertex2)
            if vertex1 in self.vertices[vertex2]:
                self.vertices[vertex2].remove(vertex1)

    def path_exists(self, start, end, visited=None):
        """Checks if there is a path from start to end."""
        if visited is None:
            visited = set()
        if start not in self.vertices or end not in self.vertices:
            return False
        if start == end:
            return True
        visited.add(start)
        for neighbor in self.vertices[start]:
            if neighbor not in visited:
                if self.path_exists(neighbor, end, visited):
                    return True
        return False
