def shortest_palindrome(s: str) -> str:
    """
    Finds the shortest palindrome that can be formed by appending characters to the end of the given string.

    :param s: The input string.
    :return: The shortest palindrome formed by appending characters to the end of the input string.
    """
    if s == s[::-1]:
        return s

    for i in range(len(s), -1, -1):
        if s[:i] == s[:i][::-1]:
            return s + s[i:][::-1]
