def find_smallest_number(numbers):
    """
    Returns the smallest integer in the given list. If the list is empty or contains no integers, returns None.

    :param numbers: List of elements which may include integers and non-integer values.
    :return: The smallest integer in the list or None if no integers are present.
    """
    if not numbers:
        return None

    smallest = None

    for number in numbers:
        if not isinstance(number, int):
            continue

        if smallest is None:
            smallest = number
            continue

        if number < smallest:
            smallest = number

