def is_valid_brackets(sequence):
    """
    Determines if the given sequence of brackets is valid.

    Args:
    sequence (str): A string containing only the characters '(', ')', '[', ']', '{', and '}'.

    Returns:
    bool: True if the sequence is valid, False otherwise.
    """
    matching_bracket = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in sequence:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if stack and stack[-1] == matching_bracket[char]:
                stack.pop()
            else:
                return False
        else:
            return False

    return not stack

