def flatten_json(y):
    """
    Recursively flattens a JSON object into a dictionary with dot-separated keys.

    :param y: The JSON object to flatten.
    :return: A dictionary with flattened keys and values.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

