    from collections import Counter

    K = 0
    prime_factor_count = Counter()

    while K <= N:
        K += 1
        if K > N:
            return -1

        current_factors = Counter()
        for j in range(2, K + 1):
            current_factors.update(prime_factors(j))

        prime_factor_count.update(current_factors)
        if all(count % 2 == 0 for count in prime_factor_count.values()):
            return K

