def bellman_ford(graph, start):
    """
    Implements the Bellman-Ford algorithm to find the shortest path from a source node to all other nodes in a weighted graph.

    Parameters:
    graph (dict): A dictionary representing the graph where keys are nodes and values are lists of tuples (neighbor, weight).
    start (str): The source node from which to find the shortest paths.

    Returns:
    tuple: A tuple containing two dictionaries:
           - The first dictionary contains the shortest distances from the source node to all other nodes.
           - The second dictionary contains the predecessors for each node in the shortest path tree.
           If a negative weight cycle is detected, returns the string "Graph contains a negative weight cycle".
    """
    distances = {node: float('infinity') for node in graph}
    predecessors = {node: None for node in graph}
    distances[start] = 0

    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                return "Graph contains a negative weight cycle"

    return distances, predecessors


