import operator

def shunting_yard(expression):
    """
    Convert an infix expression to a postfix expression using the Shunting Yard algorithm.

    :param expression: A string representing the infix expression.
    :return: A list of tokens representing the postfix expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '(': 0}
    left_associative = {'+', '-', '*', '/'}

    output_queue = []
    operator_stack = []

    def pop_operators():
        while operator_stack and operator_stack[-1] != '(':
            output_queue.append(operator_stack.pop())

    i = 0
    while i < len(expression):
        token = expression[i]

        if token.isdigit():
            j = i
            while j < len(expression) and expression[j].isdigit():
                j += 1
            output_queue.append(expression[i:j])
            i = j - 1

        elif token == '(':
            operator_stack.append(token)

        elif token == ')':
            pop_operators()
            if operator_stack and operator_stack[-1] == '(':
                operator_stack.pop()

        else:
            while (operator_stack and operator_stack[-1] != '(' and
                   (precedence[operator_stack[-1]] > precedence[token] or
                    (precedence[operator_stack[-1]] == precedence[token] and token in left_associative))):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)

        i += 1

    while operator_stack:
        output_queue.append(operator_stack.pop())

    return output_queue

def evaluate_postfix(postfix_tokens):
    """
    Evaluate a postfix expression.

    :param postfix_tokens: A list of tokens representing the postfix expression.
    :return: An integer representing the result of the evaluated expression.
    """
    stack = []
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.floordiv
    }

    for token in postfix_tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token in operators:
            b = stack.pop()
            a = stack.pop()
            result = operators[token](a, b)
            stack.append(result)

    return stack.pop()

def evaluate_expression(expression):
    """
    Evaluate a mathematical expression using the Shunting Yard algorithm.

    :param expression: A string representing the infix expression.
    :return: An integer representing the result of the evaluated expression.
    """
    postfix = shunting_yard(expression)
    return evaluate_postfix(postfix)
