    """Return the sum of x and y."""
    return x + y

def subtract(x, y):
    """Return the difference of x and y."""
    return x - y

def multiply(x, y):
    """Return the product of x and y."""
    return x * y

def divide(x, y):
    """Return the quotient of x and y, or an error message if y is zero."""
    if y == 0:
        return "Error! Division by zero."
    else:
        return x / y

def calculator():
    """Simulate a simple calculator that performs basic arithmetic operations."""
    n = int(input())
    for _ in range(n):
        operation, x, y = input().split()
        x, y = float(x), float(y)

        if operation == '+':
            print(add(x, y))
        elif operation == '-':
            print(subtract(x, y))
        elif operation == '*':
            print(multiply(x, y))
        elif operation == '/':
            print(divide(x, y))

if __name__ == "__main__":
    calculator()
```

