class Library:
    def __init__(self):
        """Initialize an empty list to store books, each book as a dictionary."""
        self.__books = []

    def add_book(self, title, author):
        """Add a book to the library with the given title and author."""
        book = {'title': title, 'author': author}
        self.__books.append(book)
        print(f"Book added: {title} by {author}")

    def remove_book(self, title, author):
        """Remove a book from the library by title and author."""
        for book in self.__books:
            if book['title'] == title and book['author'] == author:
                self.__books.remove(book)
                print(f"Book removed: {title} by {author}")
                return
        print(f"Book not found: {title} by {author}")

    def search_books(self, criteria, value):
        """Search for books by the given criteria ('title' or 'author') and value."""
        found_books = [book for book in self.__books if book[criteria] == value]
        return found_books

    def display_books(self):
        """Display all books currently in the library."""
        print("Current books in library:")
        for book in self.__books:
            print(f"{book['title']} by {book['author']}")
```

