class BookCollection:
    def __init__(self):
        """Initialize an empty book collection."""
        self.collection = []

    def add_book(self, title, author, year):
        """Add a book to the collection with the given title, author, and year."""
        book = {
            "title": title,
            "author": author,
            "year": year
        }
        self.collection.append(book)

    def remove_book(self, title):
        """Remove a book from the collection by its title."""
        self.collection = [book for book in self.collection if book["title"] != title]

    def search_book_by_title(self, title):
        """Search for a book by its title and return its details if found."""
        for book in self.collection:
            if book["title"] == title:
                return book
        return None

    def list_all_books(self):
        """Return a list of all books in the collection."""
        return self.collection

    def count_books(self):
        """Return the total number of books in the collection."""
        return len(self.collection)
