def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def largest_prime_factor(n):
    """Return the largest prime factor of a given number."""
    if n < 2:
        return None
    largest_factor = None
    while n % 2 == 0:
        largest_factor = 2
        n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i
    if n > 2:
        largest_factor = n
    return largest_factor

def largest_prime_factors(numbers):
    """Return a list of largest prime factors for a list of numbers."""
    return [largest_prime_factor(num) for num in numbers]

# Test the function
numbers = [28, 45, 97, 100, 13195]
print(largest_prime_factors(numbers))  # Output: [7, 5, 97, 5, 29]
```

