def has_cycle(graph):
    """
    Determines if a directed graph contains a cycle.

    :param graph: A dictionary representing the directed graph as an adjacency list.
    :return: True if the graph contains a cycle, False otherwise.
    """
    visited = set()
    recursion_stack = set()

    def is_cyclic(v):
        visited.add(v)
        recursion_stack.add(v)

        for neighbour in graph.get(v, []):
            if neighbour in recursion_stack:
                return True
            if neighbour not in visited:
                if is_cyclic(neighbour):
                    return True

        recursion_stack.remove(v)
        return False

    for node in graph:
        if node not in visited:
            if is_cyclic(node):
                return True
    return False
```

```python
class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new value into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper method to insert a new value into the BST recursively."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def search(self, key):
        """Searches for a value in the BST. Returns the node if found, otherwise returns None."""
        return self._search(self.root, key) is not None

    def _search(self, node, key):
        """Helper method to search for a value in the BST recursively."""
        if node is None or node.val == key:
            return node

        if key < node.val:
            return self._search(node.left, key)

        return self._search(node.right, key)

    def delete(self, key):
        """Deletes a value from the BST if it exists."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper method to delete a value from the BST recursively."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def _min_value_node(self, node):
        """Helper method to find the node with the smallest value in the tree."""
        current = node
        while current.left is not None:
            current = current.left
        return current
```
